-- Nubes de Algodón School · Curso y textos de la web
-- Paste all of it in Supabase → SQL Editor → Run. It can be run again: it never overwrites what you edited in Panel → Edición del curso.

-- ---------- Course: stages and modules (Panel → Edición del curso) ----------
-- A module carries its lessons and exercises as JSON: [{k, t, b:[[kind,text]], video?, files?:[{name,path}], draft?}]
-- k is the key progress and submissions point to, so reordering or renaming never loses anyone's work.
create table if not exists public.course_stages(
  n int primary key,
  title text not null,
  opens int not null default 0            -- days after a student starts
);
create table if not exists public.course_modules(
  n int primary key,
  stage int not null references public.course_stages(n),
  position int not null default 0,
  title text not null,
  hours numeric not null default 1,       -- tutorial hours (Completo, Signature)
  tutoria text,
  published boolean not null default true,
  plans text[] not null default '{}',     -- empty = every level ("Aplica a todos"); otherwise only these levels
  lessons jsonb not null default '[]',
  exercises jsonb not null default '[]',
  updated_at timestamptz not null default now(),
  updated_by text
);
alter table public.course_modules add column if not exists plans text[] not null default '{}';
alter table public.course_stages enable row level security;
alter table public.course_modules enable row level security;

-- Stages are only titles and dates; modules: the team sees everything, a student the published
-- modules of the stages her level includes (Etapa 1 = the first stage) that are common or meant for her level
drop policy if exists cs_read on public.course_stages;
create policy cs_read on public.course_stages for select using (public.is_nubes() or public.is_active());
drop policy if exists cs_team on public.course_stages;
create policy cs_team on public.course_stages for all using (public.is_nubes()) with check (public.is_nubes());
drop policy if exists cm_read on public.course_modules;
create policy cm_read on public.course_modules for select using (public.is_nubes() or (public.is_active() and published
  and (public.my_plan()<>'etapa1' or stage=(select min(n) from public.course_stages))
  and (cardinality(plans)=0 or public.my_plan()=any(plans))));
drop policy if exists cm_team on public.course_modules;
create policy cm_team on public.course_modules for all using (public.is_nubes()) with check (public.is_nubes());

-- The syllabus on the public web: titles only, published modules, no lesson text
create or replace function public.course_outline() returns jsonb
language sql stable security definer set search_path=public as $$
  select jsonb_build_object(
    'stages', coalesce((select jsonb_agg(jsonb_build_object('n',n,'title',title,'opens',opens)) from course_stages),'[]'),
    'modules', coalesce((select jsonb_agg(jsonb_build_object('n',m.n,'stage',m.stage,'position',m.position,'title',m.title,'hours',m.hours,'plans',m.plans,
      'lessons',coalesce((select jsonb_agg(l->>'t') from jsonb_array_elements(m.lessons) l where coalesce((l->>'draft')::boolean,false)=false),'[]'),
      'exercises',coalesce((select jsonb_agg(x->>'t') from jsonb_array_elements(m.exercises) x where coalesce((x->>'draft')::boolean,false)=false),'[]')))
      from course_modules m where m.published),'[]'))
$$;
grant execute on function public.course_outline() to anon, authenticated;

-- ---------- Texts of the public web (Panel → Editar landing) ----------
-- One row, id 'web': {section: {field: text}}. Anyone can read it (it is what the web shows); only the team writes.
create table if not exists public.site_content(
  id text primary key,
  data jsonb not null default '{}',
  updated_at timestamptz not null default now(),
  updated_by text
);
alter table public.site_content enable row level security;
drop policy if exists sc_read on public.site_content;
create policy sc_read on public.site_content for select using (true);
drop policy if exists sc_team on public.site_content;
create policy sc_team on public.site_content for all using (public.is_nubes()) with check (public.is_nubes());
grant select on public.site_content to anon;

-- Photos of the web (public: they appear on the page)
insert into storage.buckets(id, name, public) values ('web','web',true) on conflict (id) do nothing;
drop policy if exists web_team on storage.objects;
create policy web_team on storage.objects for all to authenticated using (bucket_id='web' and public.is_nubes()) with check (bucket_id='web' and public.is_nubes());

-- ---------- First version of the programme (the dossier) ----------
insert into public.course_stages(n,title,opens) values
  (1,'La profesión y tu empresa',0),
  (2,'Visibilidad y clientes',7),
  (3,'Servicios y precios',14),
  (4,'Planifica, comunícate y brilla',21)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (1,1,0,'Conceptos básicos de la profesión',1,'En esta tutoría queremos hablar contigo sobre lo que acabas de aprender. Queremos verte ilusionada, decidida, empoderada y ayudarte a transformar esa energía en motivación real para avanzar con seguridad en este camino que acabas de comenzar.',true,
  $j$[{"k":"1-0","t":"¿Qué es una wedding planner?","b":[["p","Planner?"],["p","Una Wedding Planner es una profesional que acompaña a las parejas en uno de los momentos más importantes de sus vidas, su boda."],["p","Su función no es solo coordinar proveedores o diseñar decoraciones bonitas. Es quien cuida cada detalle con mimo, quien transforma ideas en realidades y quien garantiza que todo suceda con armonía y sin estrés."],["p","Una buena Wedding Planner es organización, diseño, empatía, planificación y resolución. Es el alma invisible que hace que todo fluya."]]},{"k":"1-1","t":"Sus funciones","b":[["p","Planner?"],["p","Estas son solo algunas de las funciones esenciales:"],["li","Ayudar a distribuir correctamente el presupuesto de los novios, priorizando lo que de verdad importa."],["li","Buscar, contactar y gestionar proveedores de confianza: espacios, catering, floristas, fotógrafos, músicos, decoración, peluquería, maquillaje…"],["li","Definir el estilo de la boda y crear un diseño a medida que refleje la personalidad de la pareja."],["li","Coordinar el Gran Día siguiendo un timing detallado, resolviendo imprevistos y asegurándose de que todo salga tal como soñaron."]]},{"k":"1-2","t":"Por qué surge esta figura","b":[["p","La figura del Wedding Planner nace en Estados Unidos en los años 50, cuando las mujeres empiezan a incorporarse al mundo laboral y se necesita alguien externo para organizar las bodas."],["p","Con el tiempo, las bodas se convierten en eventos más exigentes, con más detalles, estética y expectativas. Y ahí aparece el rol profesional que garantiza que todo salga bien."],["p","En España aterriza hacia el año 2000, influenciada por las tendencias de EE.UU. y Reino Unido. Y desde entonces, no ha dejado de crecer."]]},{"k":"1-3","t":"Su importancia en una boda","b":[["p","boda?"],["p","Total. Una Wedding Planner no solo evita el estrés de los novios, optimiza el tiempo, el presupuesto, mejora el diseño, supervisa la ejecución y gestiona cada detalle para que los protagonistas disfruten de su día sin preocupaciones."]]},{"k":"1-4","t":"Qué formación necesitas","b":[["p","en una buena Wedding Planner?"],["p","Más allá de los cursos oficiales en organización de eventos y protocolo, lo que realmente marca la diferencia es dominar estas habilidades clave:"],["li","Gestión de presupuestos y proveedores"],["li","Negociación y atención al cliente"],["li","Diseño y creatividad"],["li","Comunicación efectiva y liderazgo"],["li","Nuestra experiencia nos ha enseñado que ser buena Wedding"],["li","Planner es una mezcla entre técnica, pasión, sensibilidad, firmeza y actitud profesional."]]},{"k":"1-5","t":"Reflexiones antes de empezar","b":[["p","¿Por qué he decidido convertirme en Wedding Planner?"],["p","Antes de continuar, necesitamos que tengas algo muy claro..."],["p","Es probable que hayas decidido hacer este curso porque organizaste tu propia boda y te encantó la experiencia, porque has ayudado a tus amistades a preparar celebraciones que salieron genial, o porque consideras que esta profesión es encantadora y muy especial. Pero permítenos decirte algo importante:"],["li","Ser Wedding Planner implica una responsabilidad absoluta. No se trata solo de creatividad o gusto por las fiestas; se trata de garantizar que todo un proyecto esté bien ejecutado, de cumplir con las expectativas de unos clientes que han confiado en ti y han invertido en tu trabajo. Requiere que sepas gestionar con profesionalidad cada detalle del evento, distribuir presupuestos de forma eficaz, revisar contratos minuciosamente en representación de tus parejas y estar preparada para reaccionar ante cualquier imprevisto el día de la boda."],["li","Aunque disfrutamos profundamente de nuestra profesión, esto no es un hobby ni algo que hacemos solo por diversión, como los ejemplos anteriores. Las parejas van a confiar en ti uno de los días más importantes de sus vidas, y tu responsabilidad de que todo salga perfecto será enorme."],["li","A partir de este momento, tu visión debe cambiar. Deja de ver el rol de Wedding Planner como un pasatiempo: es una profesión que exige formación, compromiso y mucha profesionalidad."],["p","Ya te habrás dado cuenta de que somos grandes fans de las frases motivadoras. Para nosotras, funcionan como verdaderos mantras que nos ayudan a creer en nuestra capacidad incluso en los momentos más difíciles de esta profesión… que, por supuesto, los hay. ¡Y FUNCIONA! Por eso, te recomendamos encarecidamente que, si en algún momento algo te parece complicado, te repitas esta frase y confíes en ti misma:"],["p","“Lo que hoy parece difícil, mañana será parte de tu historia de éxito.”"],["p","Sabemos que el punto anterior te ha hecho reflexionar, y por eso queremos dejarte esta frase. Porque sí, amiga, esto va muy en serio. Si algo hemos aprendido a lo largo de nuestra trayectoria es la importancia de respetar y valorar profundamente esta profesión, para que así lo hagan también los demás y, con ello, podamos contribuir al crecimiento del sector por el bien de todas las personas que deseamos dedicarnos a él."],["p","Así que te animamos a que tú también lo hagas: disfruta del proceso, crece y nutre tu mente con todo lo que vas a aprender en esta formación, para más adelante poder recoger los frutos de tu esfuerzo."],["p","Créenos: los recogerás. Y permítenos decirte algo muy importante: cuando algo cuesta un esfuerzo y un sacrificio... ¡El resultado vale el doble!"],["p","Lo que hoy parece difícil, mañana será parte de tu historia de éxito."],["p","Actitud Qué importante es nuestra actitud cuando decidimos dedicarnos a organizar bodas… de hecho, creemos firmemente que la actitud lo es todo."],["p","Cuando alguien está verdaderamente motivado por algo, va a por ello con todas sus fuerzas, no se rinde ante las dificultades y, lo más importante, disfruta del camino a pesar de los desafíos. Eso es precisamente lo que nosotras hemos aprendido a lo largo de estos diez años de experiencia: no todo será perfecto, pero la manera en que enfrentamos los obstáculos determinará cuánto disfrutamos de esta profesión."],["p","La clave está en comprender que cada dificultad encierra un aprendizaje valioso que impulsará nuestro crecimiento profesional y personal. Así que, ya lo sabes… no lo intentes, ¡consíguelo!"],["p","Reciclaje continuo Nuestro sector, al igual que muchos otros, está en constante evolución. Las tendencias cambian, las modas se transforman continuamente, la tecnología avanza sin pausa… y el mundo no se detiene. Por eso, la formación continua y el reciclaje profesional son absolutamente imprescindibles si no queremos quedarnos atrás."],["p","Tú misma lo comprobarás en cuanto inicies esta experiencia:"],["p","invertir periódicamente en formación será clave para mantenerte actualizada, innovadora y posicionada como una profesional de referencia en el sector."],["p","¿Tendré trabajo como Wedding Planner?"],["p","Si tu actitud es la correcta, la respuesta es: SÍ."],["p","El sector está creciendo y las parejas valoran cada vez más este servicio. Y tú, con lo que vas a aprender aquí, estarás preparada para aprovechar esa demanda."],["p","Hazlo todo con excelencia y conseguirás lo que te propongas No hay secretos, solo compromiso, esfuerzo y excelencia. Hazlo todo como si fuera para ti y los resultados llegarán."]]}]$j$::jsonb,
  $j$[]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (2,1,1,'Creación y gestión de tu empresa',2,'En esta tutoría queremos hablar contigo sobre lo que acabas de aprender y ayudarte a asimilar todos los conceptos. Queremos ayudarte en todo momento en el proceso, puede parecer complicado, pero con dedicacón podrás conseguir lo que te propongas, ¡ánimo!',true,
  $j$[{"k":"2-0","t":"Tu nicho de mercado y tu cliente ideal","b":[["p","El primer paso para crear una empresa sólida y con identidad es seleccionar tu nicho de mercado. ¿Qué es un nicho de mercado?"],["p","Es un grupo concreto de personas con intereses y necesidades específicas a quienes te vas a dirigir para organizar sus bodas."],["p","En otras palabras, tu nicho de mercado es tu cliente ideal."],["p","Es fundamental enfocar tu comunicación y servicios hacia un perfil concreto de cliente con características comunes. Así, cuando estas personas te busquen, te identificarán fácilmente y no se confundirán creyendo que ofreces bodas de estilos que no se alinean con sus gustos."],["p","Definir tu nicho con precisión es esencial para el buen funcionamiento de cualquier empresa."],["h","Cómo averiguar quién es tu cliente ideal"],["p","Para definir a tu cliente ideal (o nicho de mercado), necesitas determinar con detalle el tipo de pareja con la que deseas trabajar y el estilo de boda que quieres organizar."],["p","No te preocupes, al finalizar este módulo realizaremos un ejercicio práctico para ayudarte a definir tu nicho de mercado, pero mientras tanto ves preguntándote:"],["p","¿Qué edad tienen las parejas con las que quiero trabajar? ¿Cómo es su personalidad? ¿Qué tipo de boda sueñan? ¿Cuál es su estilo de vida? ¿Qué redes sociales utilizan? ¿Qué valores priorizan?"]]},{"k":"2-1","t":"Material para arrancar la empresa","b":[["p","Una vez definido tu nicho de mercado, el siguiente paso es crear material visual y de comunicación que te ayude a difundir tu trabajo, atraer a tu cliente ideal y comenzar a posicionarte como profesional."],["h","Redes sociales"],["p","Una vez que tengas claro tu cliente ideal y el tipo de bodas que quieres organizar, es momento de preparar material para difundir tu trabajo y atraer clientes. Algunas plataformas pueden ser de gran utilidad para lograrlo."],["p","No te preocupes, hemos dedicado un módulo completo para profundizar en la gestión de redes y medios de difusión. De momento, es suficiente que las conozcas y empieces a familiarizarte con ellas, aunque lo ideal es que, con el tiempo, puedas trabajar en varias a la vez."],["p","Desde el momento en que defines tu nicho, debes activar todas tus habilidades para conectar con ese perfil de cliente: entender cómo piensa, qué necesita y qué le interesa. Esto te permitirá ganar su confianza y posicionarte de forma visible."],["h","Shootings o editoriales"],["p","Una herramienta que nos ha hecho crecer enormemente como empresa son los shootings editoriales."],["p","Estos consisten en sesiones de fotografía y vídeo inspiradas en bodas reales (aunque no lo sean), en las que participan diversos profesionales del sector con un objetivo común:"],["p","obtener material visual de calidad para nuestras webs, portafolios y redes sociales. Este material es clave para atraer nuevos clientes."],["h","Colaboraciones con otros proveedores"],["p","La colaboración es una de las claves del éxito en nuestro sector."],["p","En una boda intervienen muchos profesionales, y todos ellos deben funcionar como piezas perfectamente encajadas en un mismo puzle. Crear comunidad y trabajar desde el respeto y la cooperación hará que todo fluya mucho mejor y te ayudará a construir una reputación positiva."],["h","Página web"],["p","Tener una página web ya no es opcional, hoy en día existen herramientas muy sencillas y asequibles para crear una web funcional, estética y profesional."],["p","Tener una web significa dar un paso más en tu posicionamiento como empresa seria y consolidada. Refleja tu identidad, muestra tu trabajo, facilita el contacto… y sobre todo, inspira confianza."]]},{"k":"2-2","t":"Proveedores del sector","b":[["p","Una parte fundamental de tu trabajo como Wedding Planner será gestionar y coordinar a los diferentes proveedores implicados en una boda. Cuanto mejor sea tu red de colaboradores, más confianza transmitirás a tus parejas."],["p","Saber elegir, cuidar y gestionar estas relaciones te posicionará como una profesional organizada, respetuosa y fiable."],["h","Cómo relacionarte con los proveedores"],["p","Mantén siempre un trato cordial con tus colegas y coopera al máximo para que el evento fluya adecuadamente. Para nosotros, la noción de equipo es esencial. Todos necesitamos apoyo en algún momento, y el compañerismo se valora enormemente."],["p","Base de datos Proveedor Estado Contacto Pagos Notas Catering ✅ Comp… 04 …"],["p","Fotografía ✏ En pr… 04 …"],["p","Vídeo ⏳ No ini… 04 …"],["p","Make up 👀 En re… 09 …"],["p","Cuando te presentas ante un proveedor como Wedding Planner, y éste está familiarizado con tu figura, comprenderá tu función en cada fase del proceso."],["h","Cómo hacer una reunión con un proveedor"],["p","Una base de datos sólida de proveedores es clave. Para ello, enfócate en tu nicho de mercado y asegúrate de verificar la calidad del servicio de cada proveedor."],["p","Antes de colaborar con uno nuevo, formula las preguntas adecuadas, revisa con atención los dosieres de servicios y precios que te envíen, y resuelve cualquier duda relevante."],["p","También es importante revisar los contratos legales que te envíen antes de que tus parejas los firmen, garantizando siempre la seguridad de tus clientes."],["h","Cómo crear tu propia base de datos"],["p","Te recomendamos firmemente desarrollar una base de datos bien organizada, clasificada por tipo de proveedor. Esto agilizará la búsqueda de servicios adaptados a las necesidades de cada cliente."],["p","Define primero con qué proveedores deseas trabajar en función de tu cliente ideal. Por ejemplo, si tu cliente ama las fiestas, busca especialistas en música, animación, iluminación, etc. Si no es su prioridad, enfócate en lo que sí lo sea para él."],["p","Grupos habituales de proveedores:"],["li","Espacios para bodas"],["li","Floristas"],["li","Fotógrafos y videógrafos"],["li","Música en directo para la ceremonia y DJ"],["li","Maestro de ceremonias"],["li","Alquiler de mobiliario"],["li","Catering"],["li","Peluquería y maquillaje"],["li","Servicios adicionales según el perfil de cliente:"],["li","Animación infantil"],["li","Espectáculos"],["li","Glitter bar"],["li","Tatuadores"],["li","Food trucks"],["li","Batucadas"],["li","Alquiler de neones, etc."],["li","Guarda sus datos en una plantilla organizada por gremios para acceder fácilmente a todos los datos cuando los necesites."],["h","Cómo negociar con proveedores"],["p","Una de las habilidades que deberás desarrollar como Wedding Planner es la capacidad de negociación. Al principio puede parecer difícil, pero con práctica y confianza, lograrás acuerdos beneficiosos tanto con clientes como con proveedores."],["p","En el Módulo 4 profundizaremos en este tema y haremos ejercicios prácticos."],["h","Cómo contrastar proveedores para garantizar la calidad"],["p","Hoy en día, dispones de múltiples recursos para contrastar la reputación de los proveedores. Puedes investigar dónde han trabajado previamente y consultar referencias."],["p","Tener buenas relaciones en el sector también te permitirá intercambiar opiniones con otros profesionales (incluso si son competencia) sobre la experiencia de trabajo con determinados proveedores."],["p","El sector nupcial, aunque amplio, es pequeño, y el espíritu de colaboración siempre genera beneficios para todos."]]},{"k":"2-3","t":"Cómo arrancar a nivel legal","b":[["p","Tras definir tu oferta de servicios y a qué cliente vas a dirigirte, es momento de cumplir con los aspectos legales necesarios para operar como empresa."],["p","No te preocupes, vamos a explicarte los pasos fundamentales, aunque también puedes contar con una gestoría de confianza que te asesore y acompañe durante el proceso y más adelante, cuando tu empresa esté en marcha."],["p","Cinco pasos clave para lanzar tu empresa legalmente:"],["h","Alta como autónomo"],["p","Puedes hacerlo tú misma, acudiendo a Hacienda y rellenando el modelo 037. Allí deberás elegir el epígrafe correspondiente a los servicios que ofreces (por ejemplo,“968.2. Organización de espectáculos”). Según tus servicios específicos, tu gestor podrá aconsejarte el más adecuado."],["h","Seguro de Responsabilidad Civil"],["p","Debes contratar este seguro para cubrirte a ti, a tus empleados o a cualquier persona o bien que pueda verse afectado durante tu trabajo."],["p","Es indispensable para protegerte ante posibles reclamaciones por daños."],["h","Ley de Protección de Datos (LOPDGDD)"],["p","Desde el momento en que recopiles datos personales, debes cumplir con la LOPDGDD. Esto implica:"],["li","Obtener el consentimiento expreso, informado y verificable."],["li","Incluir cláusulas de protección de datos en formularios, contratos y tu web."],["li","Redactar una política de privacidad que indique el tratamiento de datos y derechos de los usuarios."],["p","Por ejemplo, si incluyes un formulario de contacto en tu página web, antes de que el usuario lo envíe, debe haber una casilla marcada de forma voluntaria (nunca preseleccionada) donde declare que ha leído y acepta la política de privacidad."],["p","Lo mismo se aplica a cualquier medio por el que vayas a obtener datos personales: redes sociales, correos, presupuestos, etc."],["p","Además, estás obligada a redactar y mantener actualizada tu Política de Privacidad, donde se especifique:"],["li","Quién trata los datos."],["li","Con qué finalidad."],["li","Durante cuánto tiempo."],["li","Qué derechos tiene el usuario (acceso, rectificación, supresión, oposición, portabilidad, limitación del tratamiento)."],["li","A continuación, te mostramos un ejemplo de texto que usamos en los mails, documentos etc... y por descontado puedes usar:"],["li","CONFIDENCIALIDAD: Este mensaje y sus archivos adjuntos son confidenciales y están dirigidos exclusivamente al destinatario."],["li","Si ha recibido este correo por error, le rogamos que lo notifique de inmediato al remitente y elimine el mensaje sin reenviarlo ni copiarlo."],["li","PROTECCIÓN DE DATOS: De acuerdo con la LOPDGDD parte de un tratamiento del que es responsable [Nombre de la y/o comercial. Puede ejercer sus derechos de acceso, rectificación, supresión, oposición, limitación y portabilidad enviando un correo a [email de contacto] o mediante comunicación escrita a [dirección postal de la empresa]. Si considera que sus derechos han sido vulnerados, puede presentar una reclamación ante la Agencia Española de"],["p","3/2018 y el RGPD (UE) 2016/679, sus datos personales forman Empresa], con la finalidad de gestionar la relación profesional Protección de Datos (www.aepd.es)."],["h","Derechos de imagen"],["p","Para usar imágenes de personas en tu material promocional, necesitas su autorización por escrito. Esto aplica a fotos y vídeos utilizados en tu web, redes o campañas."],["p","Tranquila, puedes encontrar modelos de contrato de cesión de imagen en los descargables del curso."],["h","Contrato de servicios"],["p","Elabora un contrato para tu empresa que recoja toda la información legal y condiciones del servicio."],["p","Te recomendamos usar el modelo que te hemos preparado (en la carpeta de descargables), elaborado por un gestor y validado por un abogado."]]},{"k":"2-4","t":"Nombre, dominio y branding","b":[["p","Una de las cosas más importantes a la hora de arrancar tu empresa, será elegir el nombre."],["p","A pesar de parecer algo sencillo, el nombre de tu empresa debe identificarte y diferenciarte, por lo que te recomendamos que después de haber hecho una intensa reflexión sobre tu cliente ideal, intentes crear un nombre que se adapte también a sus características y te identifique."],["p","No solamente debe ser un nombre atractivo para ti sino que, como hemos comentado, debe tener carácter comercial e identificarse con tu tipo de cliente... Inspírate, investiga en el sector y se creativa, pero NO COPIES!"],["p","Deberás registrar el dominio web y por ello, debes hacer un trabajo paralelo cuando estás buscando el nombre para tu empresa ya que puedes encontrarte con que, una vez que hayas escogido este nombre, ya esté registrado por otra empresa y por lo tanto, debas cambiarlo."],["p","Para finalizar, debes crear el branding de tu empresa, diseñar un logotipo que te represente y que estará en equilibrio, una vez más, con tu nicho de mercado y tu estilo de empresa."]]},{"k":"2-5","t":"Tu imagen de empresa","b":[["p","Tu imagen e identidad es muy importante, es tu carta de presentación cada vez que cualquier cliente o proveedor te ve y vale la pena trabajarla desde el principio para que después el resto se desarrolle de forma correcta."],["p","Si tu imagen no te identifica, tus clientes y proveedores del sector se desorientarán cuando te busquen y, lo peor de todo, creerán que ofreces servicios diferentes a los que realmente ofreces."],["p","Puedes investigar bastante sobre esto y puedes crearlo tu misma, aunque siempre vamos a recomendarte que la empresa que cree tu branding, sea profesional."],["p","El diseño es un mundo aparte y va muy ligado con el marketing, lo que quiere decir que las empresas dedicadas a crear un branding van a saber perfectamente como diseñar tu logo para llegar a ese cliente que estás imaginando."],["p","Piensa que debes sentirte muy bien identificada y cómoda con este diseño porque va a acompañarte en todo durante muchísimo tiempo, tu logo es tu imagen, pero además, a partir de aquí crearás toda tu papelería, tu web, tus documentos digitales... así que es muy importante que decidas muy bien los colores que te definan, las tipografías, el estilo y que además de sentirte cómoda, lo enfoques de una forma comercial."]]},{"k":"2-6","t":"Tu plan de acción","b":[["p","Aquí te mostramos los pasos a seguir en orden para poder crear un plan de acción de empresa desde 0, te vendrá bien seguir este orden:"],["p","1- Legalizar la empresa, como hemos explicado anteriormente."],["p","2- Definir la marca y el modelo de negocio, definir tu nicho de mercado y tu estilo."],["p","3- Servicios que ofrecerá nuestra empresa. Tranquila, el módulo 5 va a dejarte claro el tipo de servicios que podemos ofrecer... tu deberás elegir a los que quieres dedicarte."],["p","4- Definir las tarifas, no te preocupes por esto ya que el modulo 6 habla ampliamente sobre ello."],["p","5- Infraestructura o lugar de trabajo en caso de que quieras o necesites trabajar en un lugar que no sea desde casa, deberás buscar de manera consciente, práctica y funcional, el lugar donde vas a trabajar y valorar qué tipo de trabajo se ejecutará allí."],["p","Si tu lugar de trabajo está de cara al público, obviamente debe estar muy bien acondicionado y ambientado siempre con un diseño que te de personalidad."],["p","6- Marketing y posicionamiento, muy importante saber difundir correctamente y sobretodo, dónde dirigirnos para captar nuestro cliente ideal y deberás estudiar bien dónde qué cantidad de dinero debes invertir en cada uno de estos aspectos."],["p","7- Marcarte un objetivo de aquí a un año en lo económico, metas y propósitos. 8- Escoger las estrategias que utilizarás."],["p","9- Definir las herramientas que necesitas para llevar tus estrategias al éxito. 10- Volcarlo todo en un calendario."],["h","Hacer un estudio de mercado"]]},{"k":"2-7","t":"Las estrategias para que tu empresa arranque","b":[["p","Una vez más insistimos en temas ya mencionados pero que van a ser finalmente estrategias que debes tener muy en cuenta a la hora de arrancar tu empresa."],["p","Algunas de estas estrategias son:"],["li","Crear una marca sólida y diferenciada"],["li","Define tu propuesta de valor: Sé clara sobre lo que te diferencia de otros Wedding Planners, ya sea en la especialización en un tipo de boda (temáticas, lujo, eco\u0002friendly, bodas de destino) o el enfoque personalizado."],["li","Desarrolla tu identidad visual: Asegúrate de que tu logo, colores y estilo estén alineados con la sensación que deseas transmitir (elegante, relajado, moderno, etc.)."],["p","Potenciar el marketing con estrategias digitales Redes sociales (Instagram, Pinterest, Facebook): Estas son plataformas visuales ideales para mostrar tu trabajo. Publica fotos de bodas que hayas organizado, videos de tu proceso y contenido inspirador. Utiliza hashtags populares como #weddingplanner, #boda, #bodas2025, etc."],["p","Asegúrate de que tu página web esté optimizada para Google, usando palabras clave relacionadas con la organización de bodas en tu área, esto ayudará a los motores de búsqueda a encontrarte. Seguro que te suena de algo, es el SEO."],["p","Escribe artículos sobre planificación de bodas, consejos para novias, tendencias en bodas, etc. Esto no solo aporta valor a los clientes, sino que también mejora tu posicionamiento en Google."],["p","Considera invertir en publicidad pagada en Facebook / Instagram Ads para segmentar parejas que planean su boda en tu localidad."],["p","Crear alianzas estratégicas con colaboraciones Establecer relaciones con floristas, fotógrafos, catering, DJs, videógrafos y decoradores son fundamentales. Además, estos proveedores pueden recomendarte a sus clientes."],["p","Colabora con los lugares más populares para bodas en tu zona. Esto puede incluir ser recomendada como coordinadora de bodas por los venues."],["p","Trabaja con influencers de bodas o personas influyentes en tu área para aumentar tu visibilidad y credibilidad."],["p","Organización y eficiencia operativa Utiliza software de gestión de bodas, plataformas como Aisle Planner o HoneyBook son herramientas útiles para gestionar tareas, presupuestos, calendarios y comunicación con los clientes."],["p","Crea plantillas para presupuestos, contratos y planificación de bodas. Esto te permitirá ser más eficiente y ofrecer un servicio más organizado."],["p","Crear una experiencia de referencia en eventos, ferias o exposiciones Exponer tus servicios en eventos como ferias o exposiciones de bodas puede ser una excelente forma de conectar con futuros clientes."],["p","Organiza eventos de networking o sesiones gratuitas de planificación de bodas en lugares estratégicos. Esto te permitirá establecer tu reputación y atraer clientes potenciales."],["p","Excelencia en el trato con el cliente Crea una experiencia memorable para las parejas estableciendo una comunicación rápida y constante con ellos. Los novios valoran mucho el estar siempre informados."],["p","Ofrece una atención individualizada que haga sentir a los novios especiales. Esto incluye una planificación detallada y un enfoque único para cada boda."],["p","Una vez finalizada la boda, solicita opiniones de los clientes para compartir en tu página web y redes sociales. Las recomendaciones de boca a boca son poderosas."],["p","Diferenciarse a través de la especialización con servicios únicos Si tienes la capacidad y los contactos, ofrecer servicios de planificación de bodas en otros lugares (playas, ciudades románticas) puede atraer a parejas que buscan algo más exclusivo."],["p","Ofrecer bodas temáticas como vintage, bohemia, ecológicas o de temporada puede atraer a parejas que buscan algo distinto."],["p","Establecer una estrategia de precios y paquetes flexibles Ofrecer varios niveles de paquetes según los servicios que incluyan (básico, intermedio, premium)."],["p","Deja espacio para que las parejas personalicen sus bodas, eligiendo los servicios que desean, en lugar de un paquete cerrado."],["p","Ofrece opciones de pago fraccionado o financiación para ayudar a las parejas a organizarse económicamente."],["p","Crear una comunidad y red de clientes En otros sectores, la fidelización de clientes es primordial, ya que si el servicio que han obtenido ha sido de su agrado, repetirán su experiencia en esa empresa..."],["p","En nuestro caso las parejas solo se casan una vez en la vida (casi siempre) y esto es algo que nos impide hacer esta fidelización como al resto de empresas, sin embargo... cuando nuestros clientes están satisfechos, entrarán a formar parte de nuestra red y este vínculo atraerá otros clientes desde ellos."],["p","Crea una comunidad en Instagram, Pinterest o incluso un blog donde puedas compartir contenido valioso (consejos, tendencias, entrevistas a proveedores, etc.)."],["p","Medir y ajustar el progreso evaluando los resultados Después de cada boda, realiza encuestas de satisfacción para evaluar la calidad de tus servicios y ajustar lo que sea necesario."],["p","Revisa qué estrategias de marketing están funcionando (redes sociales, eventos, colaboraciones) y ajusta tus esfuerzos según los resultados."],["p","Cada vez que hagas un propuesta o estrategia de marketing, preocúpate después de valorar si ha funcionado o qué aspectos puedes mejorar para tus próximas campañas."]]},{"k":"2-8","t":"Estudio de mercado y DAFO","b":[["p","Existen diversos métodos para realizar un estudio de mercado antes de lanzar tu empresa. Esto te permitirá comprender la demanda, analizar a la competencia, identificar las tendencias del sector y conocer las necesidades reales de tus potenciales clientes."],["p","A continuación, te proponemos una técnica ágil y eficaz que te ayudará a obtener información útil y ganar seguridad antes de poner en marcha tu proyecto:"],["h","Competencia"],["p","Analiza a tus competidores. Investiga las principales empresas de Wedding Planners de tu zona y averigua qué servicios ofrecen. Puedes apoyarte en herramientas como Instagram, Pinterest, TikTok e incluso la plataforma Bodas.net."],["p","Procura identificar aquello que te puede diferenciar de ellas y analiza tanto sus aspectos positivos como los negativos:"],["p","calidad de sus fotografías, nivel de interacción en redes sociales, trato al cliente, tipo de contenido que publican, tiempo de respuesta, entre otros."],["h","Tendencias"],["p","Infórmate sobre las tendencias actuales del sector. Utiliza redes sociales, blogs especializados en bodas y sitios web del ámbito nupcial para mantenerte al día y nutrirte con ideas actualizadas."],["h","Precios"],["p","Investiga las tarifas de tus competidores para tener una referencia clara del rango de precios en el mercado y valorar cómo posicionarte."],["h","Validación y evaluación de la demanda"],["p","Si tienes parejas cercanas que van a casarse o futuros clientes con los que ya estás en contacto, aprovecha para preguntarles qué servicios les interesarían y si estarían dispuestos a pagar por la asistencia de una Wedding Planner."],["h","Localización"],["p","Realiza una búsqueda rápida de la competencia en tu zona a través de Google Maps o Bodas.net para tener una visión clara del entorno competitivo local."],["p","Además, identifica los espacios cercanos que se ajusten a tu cliente ideal y averigua con qué frecuencia trabajan con Wedding Planners."],["p","Otra herramienta eficaz para estudiar tu empresa o proyecto es el análisis DAFO (también conocido como FODA o SWOT), que permite evaluar las Fortalezas, Debilidades, Oportunidades y Amenazas de tu negocio."],["h","FORTALEZAS (Factores internos positivos)"],["p","Son los aspectos internos que te otorgan ventaja frente a la competencia."],["p","Algunas preguntas clave para identificarlas son:"],["p","¿Qué hace única a mi empresa de Wedding Planner? ¿En qué somos mejores que otros profesionales del sector? ¿Qué recursos y capacidades nos diferencian?"],["p","Ejemplos de fortalezas:"],["li","Red de proveedores confiables: tener alianzas con fotógrafos, floristas, catering, etc., te permitirá ofrecer un servicio más eficiente y profesional."],["li","Servicio personalizado: organizar bodas completamente a medida, adaptadas a las necesidades de cada pareja."],["li","Experiencia y conocimiento: si ya has organizado bodas con éxito, tu experiencia representa una ventaja competitiva."],["li","Conocimiento del mercado local: conocer bien los lugares y proveedores de tu zona te permitirá asesorar mejor a tus clientes."],["li","Buena presencia online: una visibilidad sólida en redes sociales o plataformas como Bodas.net te ayudará a atraer nuevos clientes."],["li","DAFO"],["h","DEBILIDADES (Factores internos a mejorar)"],["p","Son los aspectos que pueden limitar tu crecimiento o que requieren desarrollo."],["p","Algunas preguntas clave:"],["p","¿Qué procesos necesitan optimización? ¿Qué recursos me faltan para competir mejor? ¿Qué críticas he recibido de clientes o colaboradores?"],["p","Ejemplos de debilidades:"],["li","Falta de visibilidad digital: si no tienes presencia suficiente en redes sociales o buscadores, puedes perder oportunidades."],["li","Presupuesto limitado en publicidad: la escasa inversión en marketing puede dificultar la captación de clientes."],["li","Dependencia de pocos proveedores: trabajar con pocos colaboradores limita tu flexibilidad."],["li","Falta de equipo: si trabajas en solitario, puede ser difícil asumir eventos grandes o simultáneos."],["li","Escasa experiencia en determinados tipos de bodas: si no has trabajado en bodas de destino o de lujo, puedes perder acceso a ciertos nichos."],["h","OPORTUNIDADES (Factores externos favorables)"],["p","Son situaciones o tendencias del entorno que puedes aprovechar para crecer."],["p","Ejemplos de oportunidades:"],["p","Aumento de bodas íntimas y personalizadas: muchas parejas buscan eventos más exclusivos, lo que abre nuevas posibilidades de negocio."],["p","Tendencia hacia bodas sostenibles: ofrecer opciones ecológicas (decoración reutilizable, catering orgánico) puede atraer a parejas concienciadas."],["p","Colaboraciones con influencers: trabajar con creadores de contenido especializados en bodas puede incrementar rápidamente tu visibilidad."],["p","Expansión al mercado de bodas de destino: si puedes organizar bodas fuera de tu localidad, atraerás a parejas en busca de experiencias únicas."],["p","Participación en ferias de bodas: estos eventos son una excelente plataforma para darte a conocer y generar contactos."],["h","AMENAZAS (Factores externos negativos)"],["p","Son factores que pueden afectar negativamente a tu empresa."],["p","Detectarlas a tiempo es clave para anticiparte y mitigarlas."],["p","Ejemplos de amenazas:"],["li","Alta competencia: un mercado saturado puede dificultar la captación de nuevos clientes."],["li","Inestabilidad económica: una crisis económica podría reducir el presupuesto de las parejas y disminuir la demanda de bodas."],["li","Cambios en la normativa: restricciones sanitarias o legales pueden afectar a la celebración de eventos."],["li","Cambios en el comportamiento del consumidor: algunas parejas prefieren planificar sus bodas de forma autónoma mediante apps o herramientas online."],["li","Dependencia excesiva de determinados proveedores: cualquier fallo de un proveedor clave puede comprometer la calidad de tu servicio."],["li","Conclusión del análisis DAFO"],["li","Este análisis te permitirá identificar con claridad en qué áreas debes invertir tiempo y recursos para potenciar tus fortalezas y aprovechar las oportunidades del entorno, al mismo tiempo que defines estrategias para minimizar tus debilidades y enfrentar las posibles amenazas."],["li","Por ejemplo, podrías centrarte en fortalecer tu presencia online mediante un plan de marketing digital bien estructurado, al mismo tiempo que estableces colaboraciones con proveedores sostenibles para alinearte con la creciente demanda de bodas eco-friendly."]]},{"k":"2-9","t":"Estrategias y secretos que nos han funcionado","b":[["p","En esta sección de la formación te explicaremos cómo aplicar todos los conceptos trabajados anteriormente, compartiéndote además aquellas estrategias que nosotros mismos hemos utilizado para lanzar nuestra empresa y atraer a nuestros primeros clientes potenciales."],["p","Somos conscientes de que este módulo ha sido especialmente intenso (e incluso puede que algo denso para ti), pero es fundamental atravesar esta etapa si realmente deseas crear una empresa sólida. Queremos tranquilizarte:"],["p","hemos decidido abordar esta parte desde el principio precisamente para que el resto de la formación te resulte mucho más amena y ligera."],["p","A continuación, te proponemos tres ejercicios clave, que requerirán tiempo y dedicación, pero serán esenciales para el desarrollo de tu proyecto empresarial. Así que presta atención a las siguientes páginas:"]]}]$j$::jsonb,
  $j$[{"k":"2-e0","t":"Tu cliente ideal","b":[["p","IDEAL O NICHO DE MERCADO Como ya hemos comentado, definir tu nicho de mercado y conocer a fondo a tu cliente ideal es una de las claves fundamentales para el éxito de tu empresa. Ha llegado el momento de plasmarlo por escrito."],["p","Abre un documento digital y desarrolla, con creatividad e imaginación, las siguientes características de una pareja ficticia con la que te gustaría trabajar:"],["li","Nombres de los novios"],["li","Edad de los novios"],["li","Profesión"],["li","Procedencia"],["li","Características personales"],["li","Aficiones y hobbies"],["li","Tipo de ceremonia (civil o religiosa)"],["li","Estilo de boda ideal"],["li","Una vez completado este perfil, busca imágenes que representen visualmente este tipo de boda e incorpóralas al mismo archivo. Así crearás una referencia visual y emocional muy valiosa."]]},{"k":"2-e1","t":"El nombre de tu empresa","b":[["p","DE TU EMPRESA Con tu nicho de mercado ya definido, es momento de buscar un nombre que represente a tu empresa. Para ello, te recomendamos seguir estos pasos:"],["p","1- Investiga empresas que organicen bodas similares a las que tú imaginas. 2- Analiza su branding, estética general y propuesta de valor. 3- Observa qué sensaciones transmiten sus nombres."],["p","4- Elabora una lista de 10 posibles nombres para tu empresa, basándote en esta investigación. 5- Reduce la lista a tus 4 favoritos."],["p","6- Comprueba la disponibilidad del dominio web para estos nombres."],["p","7- Finalmente, escoge el nombre que mejor te represente y con el que te sientas más cómoda."],["p","Durante esta investigación notarás cómo el nombre influye en la percepción de marca y cómo ciertas propuestas encajan mejor según el tipo de público al que te diriges. Hay quienes incluso optan por usar su propio nombre personal como marca."],["p","Es una decisión completamente personal, pero siempre debe responder a criterios comerciales, de identidad y conexión con tu cliente ideal."]]},{"k":"2-e2","t":"Tu DAFO","b":[["p","A TU EMPRESA Te proponemos realizar un análisis DAFO, una herramienta práctica para identificar los puntos clave antes de lanzar tu negocio."],["p","Crea un documento con cuatro columnas (Fortalezas, Debilidades, Oportunidades y Amenazas) y comienza a reflexionar sobre tu futura empresa."],["p","Puedes ayudarte respondiendo a las siguientes preguntas orientativas:"],["li","FORTALEZAS:"],["p","¿Qué diferencia mis servicios de los de otras empresas de Wedding Planners en la zona? ¿Qué hacemos mejor que la competencia? ¿Qué recursos poseemos que nos otorgan ventaja?"],["p","DEBILIDADES:"],["p","¿Por qué mi negocio puede tener poca visibilidad? ¿Qué factores pueden influir en una baja reputación? ¿Qué aspectos pueden estar limitando mis ingresos?"],["p","OPORTUNIDADES:"],["p","¿Puedo ampliar mis servicios y llegar a nuevos perfiles de cliente? ¿Puedo colaborar con otras empresas del sector? ¿Existen nuevas tendencias que pueda aprovechar?"],["p","AMENAZAS:"],["p","¿Qué servicios ha lanzado la competencia que pueden hacerme sombra? ¿Han aparecido nuevos competidores relevantes en mi área? ¿Quién está ofreciendo un servicio similar al mío con mejores resultados?"],["p","Si quieres, puedes utilizar la plantilla DAFO disponible en formato PDF que encontrarás en la sección de materiales descargables del curso."],["p","Este ejercicio te ofrecerá una visión más clara de tu posición en el mercado y te permitirá trazar estrategias más efectivas."],["p","D A F O DEBILIDADES AMENAZAS FORTALEZAS OPORTUNIDADES ¿Qué obstáculos enfrento? ¿Qué se me da bien? ¿Qué necesito mejorar? ¿Qué objetivos tengo?"],["p","Cuando finalices los ejercicios, envíalos a la dirección de correo hola@nubesdealgodonevents.com y agendaremos contigo tu próxima videollamada."],["p","No te preocupes si surgen dudas durante el proceso; en nuestra reunión resolveremos todas y, créenos, es ahí donde empieza la magia. ¡Enhorabuena! Has completado el Módulo 2 y no podemos estar más orgullosos de ti. ¡Lo estás haciendo fenomenal!"],["p","Sabemos que este módulo ha estado centrado en la gestión, la administración de empresa y otros aspectos internos que quizá no sean los más emocionantes para ti, pero son imprescindibles si realmente quieres emprender con éxito en este sector."],["p","Recuerda siempre:"],["li","Nadie dijo que fuera fácil... pero merece la pena. Tu Actitud, no tu Aptitud, determinará tu Altitud."]]}]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (3,2,0,'Diseña y ejecuta tu primer shooting',1,'En esta tutoría nos gustaría resolver tus dudas respecto a los shootings y editoriales, así como ayudarte a identificar a los proveedores que mas te convienen para tu estilo. No te abrumes, ve poco a poco y conseguirás llegar donde te propongas, ¡vamos!',true,
  $j$[{"k":"3-0","t":"Cómo diseñar un shooting que funcione","b":[["p","1- Lo primero que debemos hacer es definir con claridad la idea de la“boda ficticia”que queremos representar. Debemos imaginar cómo será el lugar, si se desarrollará al aire libre, y qué tipo de escenarios deseamos recrear: ceremonia, mesa principal, mesa dulce, entre otros."],["p","2- A continuación, crearemos un mood board con imágenes inspiradoras que reflejen las ideas previamente planteadas, acompañado de una paleta de colores coherente con el concepto visual que queremos transmitir. (No te preocupes, más adelante te enseñaremos cómo crear un mood board de forma efectiva)."],["p","3- Posteriormente, buscaremos a todos los proveedores necesarios que puedan colaborar en esta editorial. Para ello, les enviaremos una propuesta detallada que incluya el mood board, el espacio elegido, vestuario para los novios, fotógrafo, videógrafo, estilismo (peluquería y maquillaje), repostería creativa, decoración, floristería, pareja de modelos, entre otros elementos clave."]]},{"k":"3-1","t":"Cómo conseguir que los proveedores colaboren","b":[["p","para que quieran colaborar en tu proyecto Una vez que tengamos claramente definida nuestra inspiración y el mood board preparado, será momento de redactar un correo electrónico dirigido a los proveedores con los que deseamos colaborar en nuestro proyecto.Para ello, te recomendamos aplicar un principio que hemos mencionado en varias ocasiones y que consideramos fundamental: hazlo con excelencia y obtendrás una respuesta positiva."],["p","Para un proveedor del sector nupcial, recibir una propuesta de colaboración para un shooting implica un compromiso importante y una inversión considerable. Por ello, es esencial que tu propuesta esté cuidadosamente elaborada, transmitiendo profesionalidad y claridad, para que resulte atractiva y genere confianza."],["p","Hemos conocido a muchas compañeras que no han conseguido ejecutar con éxito sus shootings. En muchos casos, no lograron implicar a buenos proveedores, no obtuvieron la cesión de espacios adecuados, y el resultado final fue un material que no llegó a publicarse en ningún blog especializado. Aunque este último punto es debatible —ya que incluso si la editorial no es publicada, el contenido visual generado puede ser muy útil para las plataformas de difusión de todos los colaboradores—, lo cierto es que una propuesta poco trabajada limita la calidad del resultado."],["p","¿Qué puede ocurrir si la propuesta no está bien desarrollada antes de enviarla? Por ejemplo, puede que fotógrafos con experiencia no se sientan motivados a participar, lo que podría derivar en colaboraciones con profesionales menos cualificados, afectando la calidad final del material."],["p","La lección aquí es clara: si presentas una propuesta cuidada, profesional y detallada, los proveedores se sentirán entusiasmados y dispuestos a participar. Todos saldréis ganando."]]},{"k":"3-2","t":"Cómo ejecutar un shooting","b":[["p","Una vez que ya tengas confirmada la participación de todos los proveedores colaboradores, deberás fijar una fecha para la sesión. Lo más recomendable es elegir un día entre semana, ya que durante los fines de semana, es habitual que los profesionales del sector tengan otros compromisos relacionados con eventos o bodas."],["p","Cuando tengáis la fecha cerrada, redacta un correo electrónico dirigido a todos los proveedores implicados para informarles del día acordado y de la hora de inicio del shooting."],["p","La coordinación de ese día será muy similar a la de una boda real, con una diferencia clave: la ausencia del estrés del tiempo. Esto te permitirá disfrutar mucho más del proceso y atender cada detalle con calma y precisión."],["p","Unos días antes de la sesión, deberás ponerte nuevamente en contacto con todos los colaboradores para recordarles la hora, el lugar y cualquier otro detalle relevante. Además, será tu responsabilidad recoger previamente todos los elementos necesarios: vestido y traje del novio, accesorios, mobiliario, decoración y cualquier otro complemento que hayas planificado. No olvides que, una vez finalizada la sesión, todo deberá ser devuelto en perfectas condiciones."],["p","Llegado el gran día, se llevará a cabo la puesta en escena. Te trasladarás al lugar con el material y seguirás el timing que habrás elaborado previamente, ejecutando el montaje decorativo según la inspiración diseñada y coordinando la participación y ubicación de todos los proveedores."],["p","Un aspecto fundamental que no puedes pasar por alto es la autorización de los derechos de imagen por parte de los modelos. Necesitarás que firmen un consentimiento expreso que te permita utilizar el material fotográfico y audiovisual con fines de difusión. Esta gestión también recaerá sobre ti."],["p","Como en cualquier evento exitoso, el shooting será un trabajo en equipo en el que todos los colaboradores realizarán un gran esfuerzo con el objetivo común de obtener un resultado de calidad."]]},{"k":"3-3","t":"Cómo difundir tu shooting","b":[["p","Una vez finalizada la sesión y devuelto todo el material prestado a sus respectivos propietarios, llega el momento de esperar a que el fotógrafo y el videógrafo editen el contenido para que pueda ser difundido."],["p","Cuando recibas el material, es fundamental no publicarlo aún en redes sociales ni en las páginas web de los proveedores. Los blogs especializados en bodas suelen exigir exclusividad, y si la propuesta les interesa, querrán ser los primeros en publicarla. Si descubren que las imágenes o el vídeo ya han sido compartidos previamente, muy probablemente rechacen la publicación."],["p","El paso final consiste en redactar un correo electrónico acompañado de una nota de prensa donde expliques el concepto del shooting, la inspiración que lo originó, los proveedores que han colaborado, el espacio utilizado, y cualquier otro detalle relevante. Esta nota de prensa debe enviarse a diversos blogs del sector nupcial con el fin de lograr su publicación."],["p","Tranquila, en los descargables te dejaremos un ejemplo real:"],["p","uno de nuestros mood boards y la nota de prensa de una de nuestras editoriales, que podrá servirte como referencia."],["p","Además, como ya sabes, tendrás la oportunidad de asistir a nuestro próximo shooting, donde podrás ver de primera mano cómo se lleva a cabo todo este proceso y contrastar lo que has aprendido hasta ahora."],["p","Sabemos que este mundo puede parecer abrumador al principio, pero con tiempo, dedicación y pasión, te pondrás al día y lograrás todo lo que te propongas. ¡Estamos totalmente seguros de ello!"]]},{"k":"3-4","t":"Estrategias y secretos que nos han funcionado","b":[["p","En esta parte de la formación, te explicaremos cómo desarrollar todos los puntos que hemos tratado anteriormente y compartiremos contigo todo aquello que a nosotras nos ha funcionado para poner en marcha nuestra empresa y atraer a nuestros primeros clientes potenciales."]]}]$j$::jsonb,
  $j$[{"k":"3-e0","t":"Tu primer shooting","b":[["p","INVESTIGACIÓN En este módulo, tu tarea principal será asimilar e investigar en profundidad los contenidos que acabamos de tratar. Te recomendamos anotar todas las dudas que puedan surgirte en un documento digital."],["p","Envíanoslo a la dirección mail hola@nubesdealgodonevents.com y programaremos nuestra próxima videollamada para hacer la tutoría de este modulo"],["p","¡FELICIDADES! Has completado el Módulo 3 y no podemos estar más contentos por ti. Estamos seguros de que tu mente está llena de ideas, inspiración y ganas de poner en práctica todo lo aprendido. ¡Nos morimos de ganas de escucharte en nuestra próxima videollamada y conocer todos esos avances! Y no lo olvides nunca:"],["li","Crecer es atreverse a crear lo que todavía no existe."]]}]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (4,2,1,'Captación de cliente potencial',2,'En esta tutoría nos gustaría hacer una reunion ficticia, nosotros somos la pareja, y tu la wedding planner, pondrás en practica todo lo aprendido y estamos seguros de que te será super útil!',true,
  $j$[{"k":"4-0","t":"Dónde está tu cliente ideal","b":[["p","Para identificar dónde se encuentra tu cliente ideal, es fundamental que realices un estudio detallado de distintos factores que te ayuden a despejar cualquier duda."],["p","Pero no te preocupes, hoy en día contamos con múltiples herramientas que te facilitarán este proceso. Algunas de las más útiles son:"],["li","Investiga en redes sociales: Busca empresas similares a la tuya que trabajen con el mismo perfil de cliente que deseas atraer."],["li","Analiza tu zona geográfica: Averigua si los espacios y fincas cercanos trabajan con tu tipo de cliente ideal y comienza a establecer vínculos con ellos."],["li","Utiliza hashtags estratégicos: Etiquetas como pueden ayudarte a localizar contenido y perfiles relacionados con tu público objetivo. clientes muestran y, sobre todo, lee los testimonios que publican para identificar patrones de comportamiento, intereses y necesidades. conectar con aquellas parejas que realmente buscan lo que tú ofreces."],["p","#destinationwedding, #bodamediterranea o #bodaintima Explora las webs de tu competencia: Observa qué tipo de Este proceso te permitirá afinar mucho más tu estrategia y MÓDULO 4 – CAPTACIÓN DEL CLIENTE POTENCIAL"]]},{"k":"4-1","t":"Cómo atraer a tu cliente ideal","b":[["p","Una de las mayores inquietudes al emprender un proyecto es cómo atraer a los primeros clientes. A continuación, te compartimos algunas claves que te ayudarán a conectar con tu cliente ideal:"],["li","Web visible y activa: Como mencionamos anteriormente, contar con una página web posiciona tu empresa de forma consolidada en el mercado. Actualmente, crear una web no es tan complejo, pero ¡cuidado! Lo más importante no es la cantidad, sino la calidad."],["li","Si decides crearla por tus propios medios, asegúrate de que sea sencilla pero clara, enfocada a tu tipo de cliente y que transmita un contenido de calidad."],["li","Todo lo que muestres será reflejo de tu imagen profesional, así que si aún no tienes material de calidad, es preferible esperar y empezar a generarlo."],["li","Puedes comenzar con una landing page sencilla que te otorgue presencia online y, más adelante, convertirla en una web completa diseñada por profesionales."],["li","Redes sociales: Hoy en día, la visibilidad lo es todo, y las redes sociales serán tus grandes aliadas. Establece como objetivo publicar contenido de forma periódica, organiza un calendario de publicaciones y cúmplelo con constancia."],["li","A menudo dedicamos mucho tiempo a la gestión interna y olvidamos que si no somos visibles, no existimos para nuestros potenciales clientes."],["li","Crea un blog: Comparte tus experiencias como emprendedora, explica tus servicios, relata tus visitas o reuniones... Aunque te parezca irrelevante, a los clientes les encanta conocerte y saber cómo trabajas. El blog es una herramienta muy eficaz para transmitir cercanía y profesionalidad."],["p","Portafolio cuidado y profesional: Muestra tu trabajo real de forma visual, clara y ordenada. Poco a poco irás generando contenido útil para este apartado, pero recuerda: todo lo que incluyas debe representar tus mejores trabajos y contar con un nivel de calidad elevado."],["p","Crea comunidad: La colaboración con otros profesionales del sector es una de las claves del éxito. Establecer buenas relaciones te permitirá participar en eventos, generar colaboraciones y crear una red de apoyo mutuo."],["p","Incluso, cuando una pareja solicite una fecha que ya tienes ocupada, podrás recomendar a un compañero, y ellos harán lo mismo por ti."],["p","Participa en ferias de bodas: Si se organiza una feria cuyo público objetivo coincide con tu cliente ideal, puede ser una inversión muy efectiva para darte a conocer y captar nuevos clientes."],["p","Fideliza y genera confianza: Fortalece los lazos tanto con tus compañeros del sector como con tus parejas. Publicar testimonios de clientes satisfechos o referencias de otros profesionales acerca de tu forma de trabajar genera credibilidad y transmite profesionalismo."]]},{"k":"4-2","t":"Cómo preparar la reunión de captación","b":[["p","Y llegó el momento... Tras lanzar tu empresa y ponerla en marcha, recibes tu primera solicitud de unos clientes. Pero, ¿cómo afrontar esta primera reunión?"],["p","Debes tener en cuenta que las reuniones de captación son una herramienta fundamental para atraer y convencer a tus potenciales clientes. Es tu oportunidad de oro para causar una excelente impresión, generar confianza y conseguir que deseen contratar tus servicios. Por eso, es crucial que te prepares al máximo y transmitas seguridad."],["p","Para que una reunión de captación sea realmente efectiva, hay dos claves esenciales que debes tener siempre en cuenta:"],["p","1- Tener bien preparados los documentos que vas a compartir con los clientes: Es fundamental contar con una presentación clara, visual y profesional que refleje quién eres, qué ofreces y cómo trabajas. El dossier de servicios, el portafolio y cualquier otro material que respalde tu propuesta deben estar listos y alineados con tu marca. 2- Estar segura de ti misma y del servicio que vas a ofrecer:"],["li","Debes conocer perfectamente tus servicios, precios, procesos de trabajo y estilo. Esto te permitirá explicar con claridad, resolver dudas con confianza y transmitir la seguridad necesaria para que tus clientes sientan que están en buenas manos."],["li","Recuerda: esta primera reunión no solo trata de hablar, sino de escuchar también. Comprende bien las necesidades de la pareja, conéctate emocionalmente con ellos y adapta tu propuesta para que se sientan comprendidos y entusiasmados."],["li","Esa conexión marcará la diferencia."],["h","Cómo preparar la documentación que necesitas"],["p","Para las reuniones de captación de clientes, es imprescindible que tengas preparado un documento claro y atractivo en el que expliques con detalle los servicios que vas a ofrecer: tu dossier de servicios (sin incluir precios)."],["p","Este documento será una herramienta clave para presentar tu propuesta de valor, especialmente si la reunión se realiza por videollamada. En ese caso, podrás compartir la pantalla y guiar a los clientes paso a paso por todo lo que incluye tu trabajo, explicándolo de manera ordenada y profesional."],["p","Debe tratarse de un material completo, pero conciso y fácil de entender, pensado para transmitir de forma eficaz todos los beneficios que obtendrán al contratarte. Utiliza un lenguaje cercano y estrategias que generen confianza y conexión emocional. Tu objetivo será demostrar que comprendes perfectamente sus necesidades y que tú eres la persona adecuada para ayudarlos a cumplir su sueño."],["p","Este dossier puede incluir:"],["li","Imágenes de tu equipo de trabajo para humanizar tu marca."],["li","Fotografías de eventos anteriores que hayas organizado."],["li","Testimonios de otras parejas satisfechas que respalden tu profesionalidad y experiencia."],["li","Recuerda: una presentación cuidada y profesional puede marcar la diferencia. (En los descargables encontrarás nuestro portafolio/dossier como ejemplo para que puedas inspirarte)."],["h","Cómo preparar tu presencia y actitud para cerrar clientes"],["p","Es fundamental que te prepares adecuadamente antes de cualquier reunión con una pareja, tanto a nivel interno como externo."],["p","Debes sentirte segura de lo que ofreces y mostrarte empoderada, valorando tu trabajo como se merece. A través de una comunicación estratégica, transmite todas las ventajas que obtendrán si deciden contratarte. No se trata solo de hablar de lo que haces, sino de hacerlo con confianza, destacando el impacto positivo que tendrás en su gran día."],["p","Durante la reunión, mantén una escucha activa y empática."],["p","Recuerda que para ellos, su boda es un proyecto profundamente emocional que compartirán contigo con gran ilusión. Tú serás la responsable de materializar esa visión, por lo que es esencial que desde el primer momento sientan que pueden confiar plenamente en ti."],["p","Toma nota de toda la información relevante que te proporcionen y haz preguntas clave que te ayudarán a entender mejor sus expectativas:"],["p","¿Qué tipo de boda están imaginando? ¿Cuántos invitados planean tener? ¿Será una ceremonia civil o religiosa? ¿Cuál es su presupuesto aproximado? ¿Cómo visualizan el ambiente o estilo de su boda? ¿Cuáles son sus principales prioridades?"],["p","Sé siempre cordial, muestra una actitud abierta y mantén una sonrisa genuina. Tu relación con la pareja puede durar incluso dos años, así que establecer desde el principio un buen \"feeling\"mutuo será crucial para que todo fluya con naturalidad a lo largo del proceso."],["p","Cuida también tu presencia e imagen personal, ya que serán tu carta de presentación. La primera impresión cuenta, y mucho."],["p","Por último, recuerda:"],["li","Sé puntual: esto reflejará tu profesionalidad y compromiso."],["li","No vayas con prisas, organiza tu tiempo para llegar tranquila."],["li","Antes de la reunión, repítete mentalmente afirmaciones positivas, sonríe y cree en ti:"],["p","¡Vas a conseguirlo!"]]},{"k":"4-3","t":"La documentación antes y después de la reunión","b":[["p","clientes antes y después de tu primera reunión Antes de la reunión, simplemente deberás enviar un correo electrónico cordial y profesional, en el que adjuntes tu dossier de servicios y confirmes la fecha y hora de la videollamada."],["p","Aprovecha este mensaje para transmitir tu ilusión y agradecimiento por el interés que han mostrado en tu trabajo."],["p","Esa calidez será el primer paso para establecer una buena conexión."],["p","Una vez finalizada la reunión, es muy importante recopilar toda la información obtenida y volcarla en una ficha personalizada que habrás creado para estos clientes. Esta ficha te permitirá hacer un seguimiento detallado de sus necesidades, preferencias y cualquier dato relevante para su boda."],["p","Posteriormente, enviarás un correo de agradecimiento, en el que harás un pequeño resumen de lo hablado durante la reunión, expresando de nuevo lo emocionada que estás de poder formar parte de este proceso tan especial. En ese mismo email, adjuntarás el presupuesto personalizado que incluirá:"],["li","Tus honorarios como Wedding Planner"],["li","Posibles extras o servicios adicionales que puedan necesitar"],["li","Este paso marcará el inicio de una relación profesional basada en la confianza, la claridad y la ilusión compartida por hacer de su boda un día inolvidable."]]},{"k":"4-4","t":"Psicología aplicada a la captación","b":[["p","Como ya hemos mencionado anteriormente, es fundamental aplicar la psicología durante nuestras reuniones con los clientes y practicar una escucha activa y empática, que les permita expresar todas las emociones y expectativas que han depositado en este gran proyecto."],["p","Además, debes tener siempre presente que cada pareja es única: cada una tendrá inquietudes, intereses y necesidades diferentes. Por ello, tu capacidad para leer entre líneas, detectar inseguridades o puntos débiles durante esa primera reunión, y convertirlos en oportunidades para conectar y aportar soluciones, será clave para que te vean como la profesional que necesitan."],["p","Utiliza tu sensibilidad y criterio para adaptar tu discurso, resolver sus dudas y mostrarles cómo puedes hacer realidad la boda que imaginan, generando así un vínculo de confianza desde el primer momento."]]},{"k":"4-5","t":"Estrategias y secretos que nos han funcionado","b":[["p","En esta sección de la formación, te explicaremos detalladamente cómo desarrollar todos los aspectos mencionados anteriormente y compartiremos contigo todo lo que a nosotras nos ha funcionado de forma real y efectiva para poner en marcha nuestra empresa y atraer a nuestros primeros clientes potenciales."]]}]$j$::jsonb,
  $j$[{"k":"4-e0","t":"La primera reunión","b":[["p","En este módulo te proponemos un ejercicio que, aunque al principio pueda parecerte algo surrealista, es realmente poderoso y altamente efectivo."],["p","1- Imagina que has recibido tu primera solicitud de clientes interesados en contratar tus servicios. Se trata de Cristina y David, una pareja que quiere casarse en un entorno mediterráneo y planea una boda con aproximadamente 100 invitados. Has agendado una videollamada con ellos para conoceros y presentarles tu propuesta."],["p","2- Con esta información, vas a preparar esa reunión (tranquila, es solo un ejercicio práctico para trabajar tu actitud; la información sobre tus servicios puede ser ficticia)."],["p","3- Lo primero que harás será anotar las preguntas clave que quieras hacerles. Después, piensa detenidamente cómo debe ser tu actitud durante el encuentro: profesional, empática y segura. Si lo necesitas, prepara un pequeño guión que te ayude a estructurar tu presentación, organizar las ideas y anticiparte a posibles preguntas."],["p","4- Ahora, ¡llega el momento clave! Ponte frente a un espejo y ensaya tu presentación."],["p","5- Sí, lo has leído bien. Hablar frente a un espejo, aunque pueda parecer simple o incluso incómodo, es una herramienta muy útil para ganar confianza. Muchas veces ese pudor que sentimos al mirarnos refleja inseguridades internas, y al enfrentarlas, te sentirás mucho más preparada."],["p","Observa tu lenguaje corporal, tu expresión facial, tu tono de voz y cómo transmites tus ideas. Practica esa sonrisa con la que conquistarás a tus futuros clientes y asegúrate de que proyectas seguridad, entusiasmo y profesionalidad."],["p","Cuando hayas finalizado tu preparación, escríbenos a hola@nubesdealgodonevents.com para agendar tu próxima videollamada."],["p","En esa reunión, resolveremos cualquier duda que te haya surgido y realizaremos una simulación de captación de cliente para que practiques en un entorno real y sin presión."],["p","Prepárate porque será una oportunidad ideal para vencer la vergüenza, adquirir seguridad y recibir todas las estrategias que necesitas para comenzar a atraer a tu cliente ideal. ¡Estamos deseando verte en acción!"],["p","¡ESTAMOS MUY FELICES POR TI!"],["p","Has superado el Módulo 4 y no podemos estar más orgullosos."],["p","Estamos seguros de que estás absorbiendo muchísimo conocimiento y creciendo con cada paso."],["p","Nos vemos muy pronto en la próxima videollamada y, mientras tanto, recuerda siempre:"],["li","Emprender es convertir desafíos en aprendizajes y sueños en realidades."]]}]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (5,3,0,'Tus servicios',2,'En esta tutoría nos centraremos en todo lo que hemos hablado anteriormente, resolviendo dudas y ayudándote en lo que necesites para crear tu Mood Board.',true,
  $j$[{"k":"5-0","t":"Qué servicios ofrecerá tu empresa","b":[["p","Antes de elaborar tu dossier de servicios, es fundamental que decidas con claridad cuáles de ellos vas a ofrecer en tu empresa y, por tanto, en cuáles vas a especializarte profesionalmente."],["p","Existen empresas de Wedding Planners que se dedican a realizar una organización integral, lo que implica acompañar a la pareja desde el inicio y ayudarlos en todos los aspectos relacionados con la planificación, diseño y coordinación de su boda. Por otro lado, hay empresas que prefieren especializarse exclusivamente en uno de estos tres servicios: organización, coordinación o diseño."],["p","Elegir centrarte en un solo servicio también puede ser una estrategia para diferenciarte dentro del sector. Por ejemplo, si decides convertirte en una empresa especializada en Wedding Design, estarás delimitando un nicho de mercado más concreto. Las parejas acudirán a ti específicamente para contratar servicios relacionados con la decoración de su boda, lo cual te posicionará como especialista y profesional reconocida en ese ámbito en particular."]]},{"k":"5-1","t":"Definición de cada servicio","b":[["p","A continuación, vamos a definir brevemente cada uno de los servicios que puede ofrecer una empresa de Wedding Planner."],["p","Conocer en qué consiste cada uno te permitirá decidir con mayor claridad cuál se adapta mejor a tu perfil profesional y al tipo de empresa que deseas construir. Además, esta definición te ayudará a comunicar de forma clara y profesional a tus futuros clientes qué incluye cada servicio y cómo puedes ayudarles en su gran día."],["h","Organización integral"],["p","La Organización Integral, también conocida como planificación completa de una boda, implica acompañar a la pareja desde el inicio del proceso hasta el gran día. Este servicio abarca absolutamente todo: desde la búsqueda del lugar ideal y la selección de cada proveedor necesario, hasta el diseño detallado de todos los espacios y, por supuesto, la coordinación total durante el día de la boda para que todo se desarrolle a la perfección."],["h","Diseño"],["p","El Diseño de una boda consiste en la creación cuidadosamente planificada de cada uno de los espacios en los que se desarrollarán los distintos momentos del evento. Este servicio se enfoca en definir la estética, el estilo y la ambientación de cada escenario, asegurando que todo esté en armonía con la visión de la pareja y que cada detalle contribuya a crear una experiencia visual y emocional única."],["h","Coordinación del día de la boda"],["p","La Coordinación de la boda implica el acompañamiento y la supervisión detallada de todo el desarrollo del día del evento, siguiendo un timing previamente elaborado junto a los novios y los proveedores implicados. Este servicio garantiza que cada momento ocurra según lo planificado, resolviendo imprevistos y asegurando que todos los elementos fluyan en perfecta sincronía para que la pareja pueda disfrutar de su gran día sin preocupaciones."]]},{"k":"5-2","t":"Organización integral","b":[["p","Como ya mencionamos en el módulo anterior, la Organización Integral es un servicio completo que brinda apoyo a la pareja en absolutamente todo lo que puedan necesitar para su gran día. Desde el primer contacto hasta la ejecución final, estarás a su lado en cada paso del camino, asegurándote de que cada decisión, elección y detalle esté perfectamente alineado con sus deseos y necesidades."],["h","Cómo llevar a cabo este servicio con una pareja"],["p","Para llevar a cabo una Organización Integral eficaz, es fundamental seguir una serie de pasos que aseguren una gestión completa y profesional del proceso. A continuación, te detallamos cómo hacerlo:"],["li","Búsqueda y gestión de proveedores"],["li","Cuando una pareja contrata el servicio de organización integral, suele significar que parte desde cero: no ha contratado aún a ningún proveedor y necesita tu apoyo en todos los aspectos relacionados con su boda. Tu papel será clave desde el primer momento."],["li","Lo primero que deberás hacer es averiguar con precisión cuál es el presupuesto disponible. Una vez tengas esta información, trabajarás junto a la pareja para crear una\"escalera de prioridades\"que os ayude a definir qué servicios son esenciales y cuáles pueden adaptarse o ajustarse."],["p","Crea una tabla donde puedas distribuir de forma estimada el presupuesto entre los distintos proveedores que necesitarán."],["p","Para cada proveedor, añade:"],["li","El presupuesto estimado asignado."],["li","Una casilla para comprobar si ese presupuesto ha sido respetado o no."],["li","Una columna final con la diferencia (positiva o negativa) respecto al importe inicialmente previsto."],["li","Esta tabla te servirá como una herramienta de control de gastos muy útil, que te permitirá llevar un seguimiento detallado del presupuesto real conforme se vayan cerrando acuerdos con los proveedores."],["li","No te preocupes si todo esto te resulta algo complejo al principio: en los descargables encontrarás la plantilla que usamos nosotros para nuestras bodas. Revísala para verlo más claro."],["li","Una vez tengas clara la hoja de ruta presupuestaria, comienza la búsqueda de proveedores. El primer paso es encontrar el espacio o venue para la celebración:"],["li","Si la pareja vive cerca, realiza las visitas con ellos."],["li","Si son de fuera, visita tú misma los espacios previamente y elabora dossieres informativos con los detalles más importantes."],["li","Asegúrate de que el espacio encaja a la perfección con lo que buscan en cuanto a estilo, capacidad, presupuesto y servicios ofrecidos."],["li","Es importante tener en cuenta que algunos espacios cuentan con proveedores en exclusiva o servicios internos (como cocina propia). Hasta que no se haya elegido el espacio, no podrás avanzar con el resto de contrataciones."],["p","Recomendaciones clave al ofrecer proveedores Siempre presenta varias opciones para que la pareja pueda elegir según sus preferencias."],["p","Asegúrate de que el proveedor que recomiendas ofrece un servicio de calidad contrastada. Recuerda: tú eres la responsable ante cualquier inconveniente."],["p","Verifica que el proveedor se adapta al estilo y presupuesto de la pareja."],["p","Confirma la disponibilidad del proveedor en la fecha de la boda."],["p","Conforme vayáis contratando proveedores, continúa actualizando la tabla de control de gastos y recuerda a tus clientes los plazos de pago acordados con cada uno."],["p","Además, es imprescindible que revises detenidamente los contratos antes de que sean firmados por tus parejas. Revisa bien todas las cláusulas: si encuentras alguna ambigua o que no proteja los intereses de tus clientes, habla con el proveedor para modificarla por otra más clara y segura."],["p","Este proceso meticuloso será la base de una planificación impecable y profesional, garantizando la tranquilidad de tus clientes y la excelencia en tu trabajo como Wedding Planner."]]},{"k":"5-3","t":"Diseño y mood board","b":[["p","Como ya hemos mencionado, el Diseño de una boda consiste en la planificación y creación cuidada y estratégica de cada uno de los espacios donde se desarrollarán los diferentes momentos del evento. Esto incluye desde la ceremonia hasta el banquete, la zona de cóctel, la mesa dulce o cualquier otro rincón especial que forme parte del día."],["p","Cada espacio debe ser pensado no solo desde un punto de vista estético, sino también funcional, transmitiendo la esencia de la pareja, respetando su estilo y creando una atmósfera coherente y armoniosa durante toda la celebración. El diseño debe emocionar, sorprender y hacer que cada instante se convierta en una experiencia única para los novios y sus invitados."],["h","Cómo llevar a cabo este servicio con una pareja"],["p","Para comenzar con el diseño de una boda, es fundamental tener en cuenta dos factores clave: el estilo de la pareja y el lugar donde se celebrará cada uno de los momentos del evento. Estos elementos serán la base sobre la cual construiremos una propuesta personalizada, coherente y con identidad."],["p","Como primer paso, solicitaremos a la pareja una recopilación de imágenes de inspiración. Este material visual nos permitirá comprender mejor sus gustos, referencias estéticas y sensaciones deseadas. No obstante, es importante recordar que estas imágenes deben servir únicamente como guía: los novios no son profesionales del diseño y muchas veces sus ideas necesitan ser orientadas, ajustadas o reinterpretadas."],["p","Nuestro trabajo será tomar esa inspiración inicial, enriquecerla con nuevas ideas, incorporar tendencias actuales y, sobre todo, adaptarla al entorno, a la esencia de la pareja y al estilo propio del evento. Jamás debemos copiar literalmente una imagen de referencia; al contrario, debemos utilizarla como punto de partida para desarrollar un diseño único, auténtico y cargado de personalidad."],["p","El objetivo de este servicio es precisamente ese: crear bodas con alma, que hablen de quienes se casan, que respiren su identidad y que emocionen. Copiar sería renunciar a todo esto."],["p","Crear es lo que realmente marcará la diferencia."],["h","Cómo trabajar el diseño en una boda"],["p","Para desarrollar un diseño de boda coherente, estético y personalizado, es fundamental seguir una serie de pasos estructurados que te permitan convertir la inspiración inicial en una propuesta sólida y ejecutable. Aquí te explicamos cómo hacerlo:"],["h","Crear una paleta de colores"],["p","El primer paso consiste en definir, junto a la pareja, una paleta cromática que servirá de hilo conductor para todo el evento."],["p","Esta decisión debe estar supervisada por ti para asegurar la armonía visual y el equilibrio entre todos los elementos:"],["p","papelería, invitaciones, seating plan, sitting plan, detalles y, por supuesto, el entorno."],["p","Es esencial tener en cuenta el espacio y su contexto. Por ejemplo, si la boda se celebra en una finca rodeada de flores rojas en esa época del año, es recomendable que la paleta se complemente con estos tonos, en lugar de competir con ellos."],["p","Lo mismo aplica a texturas y estilos predominantes en el lugar de celebración."],["p","Ejemplo real: En una ocasión, presentamos tres paletas de color a una pareja. Tras su elección, utilizamos esa selección como base para todo el diseño de su boda, garantizando una estética uniforme y cuidada."],["h","Elaborar un mood board o tablero de inspiración"],["p","Con las imágenes proporcionadas por la pareja y las ideas que tú aportes, se crea un primer mood board que plasme visualmente el estilo deseado. Este tablero te servirá como herramienta clave para:"],["li","Confirmar que estáis alineados en cuanto a estética y sensaciones."],["li","Transmitir claramente la propuesta al resto de proveedores."],["li","Guiar todo el proceso de diseño con coherencia."],["li","A partir de este mood board inicial, se segmentarán todos los aspectos y espacios a diseñar, desarrollando ideas específicas para cada uno de ellos, tales como:"],["li","Papelería (invitaciones, menús, cartelería, etc.)"],["li","Decoración de mesas"],["li","Arreglos florales"],["li","Mobiliario"],["li","Espacio de ceremonia"],["li","Ramo de novia"],["p","Una vez definido el diseño de cada área, comienza la fase de producción. Esto implica:"],["li","Contactar con proveedores especializados para crear los elementos personalizados que requieras."],["li","Visitar showrooms de empresas de mobiliario para elegir las piezas que mejor encajen con tu propuesta."],["li","Encargar la producción de invitaciones, detalles y cualquier otro elemento decorativo."],["li","Coordinar cada fase para garantizar que todo llegue en tiempo y forma para el día de la boda."],["li","Este proceso, aunque detallado, es el que permite que cada boda tenga una identidad propia y esté cuidada hasta en el más mínimo detalle."],["h","Métodos de inspiración"],["p","Sin duda, el diseño es el servicio más creativo dentro de la organización de una boda y, al mismo tiempo, uno de los que más atrae a las parejas. Es precisamente a través del diseño como logramos que una boda se distinga de otra, marcando la diferencia mediante la personalización y la estética cuidada."],["p","Por eso, la clave para poder ofrecer propuestas únicas e innovadoras radica en la inspiración."],["p","Puede parecer curioso, pero cualquier experiencia cotidiana puede convertirse en una valiosa fuente de inspiración. Así lo aprendimos de los diseñadores con los que nos hemos formado, así lo afirman los grandes referentes del sector y, sin duda, así lo hemos confirmado con nuestra propia experiencia."],["p","Por ejemplo, si estás trabajando en una boda con un aire claramente italiano, ver una película ambientada en Italia puede ayudarte a captar pequeños detalles culturales que luego podrás trasladar al diseño del evento. O si la pareja desea un estilo romántico, inspirarte en escaparates que utilicen iluminación tenue o delicada puede darte ideas para crear una atmósfera similar."],["p","La clave está en alimentar constantemente tu creatividad, y no solo a través de internet, redes sociales o páginas especializadas, sino también desde lo sensorial y tangible:"],["p","pasea por tu ciudad, observa la naturaleza, explora tiendas, presta atención a los colores, texturas, aromas… Cualquier entorno puede convertirse en una fuente valiosa de ideas."],["p","Un consejo muy útil: lleva siempre contigo una pequeña libreta o utiliza una app de notas en tu móvil. Nunca sabes cuándo surgirá una idea brillante que pueda convertirse en un elemento clave para uno de tus diseños. Y si no la apuntas en el momento, lo más probable es que la olvides. ¡Lo decimos por experiencia!"],["h","Cómo elaborar un Mood Board de forma correcta"],["p","Crear un buen tablero de inspiración o mood board no es una tarea sencilla. De hecho, puedo asegurarte que es imposible explicarlo completamente en unas pocas líneas, ya que intervienen numerosos elementos relacionados con el diseño que deben estudiarse y entenderse con profundidad antes de comenzar su elaboración."],["p","Sin embargo, si tienes claro que deseas ofrecer este tipo de servicio dentro de tu empresa, te recomendamos que sigas los siguientes pasos básicos para empezar a trabajar de forma profesional:"],["p","1- Define la paleta de colores:"],["li","Como ya comentamos anteriormente, esta debe ser el punto de partida de tu mood board."],["li","Inclúyela claramente en el diseño, ya que funcionará como referencia visual para toda la decoración."],["li","Todos los elementos deberán estar en armonía con esta selección cromática."],["p","2- Incluye imágenes de inspiración de la pareja y propias:"],["li","Añade las fotografías que te haya enviado la pareja y complétalas con tus propias propuestas. Junto a cada imagen, incluye textos explicativos en los que justifiques tus sugerencias, añadas ideas o argumentes por qué ciertas propuestas quizás no sean viables por cuestiones de entorno, estilo o tendencias."],["li","Este paso es esencial para guiar adecuadamente a la pareja hacia un diseño coherente y realista."],["li","Integra imágenes de los espacios a decorar: Para cada zona clave del evento (ceremonia, cóctel, banquete, etc.), incorpora imágenes del espacio en cuestión junto a las inspiraciones correspondientes, siempre acompañadas de una descripción de tus ideas para ese lugar."],["li","Inspírate en los detalles decorativos: Añade referencias visuales para elementos como la papelería, seating plan, sitting plan, detalles de bienvenida u otros complementos que deban alinearse con el diseño global."],["li","Diseño floral: No olvides incluir una sección específica para el diseño floral, con inspiración visual que complemente el resto de la decoración y siga la misma línea estética."],["li","Una vez terminado el mood board, envía la propuesta a la pareja y reflexionad juntos sobre ella. Es importante que el diseño final sea el resultado de una colaboración entre tus conocimientos y su visión personal."],["li","Si decides especializarte en el servicio de Wedding Designer, te animamos firmemente a formarte de manera específica en este campo. Profundizar en diseño, composición, armonía visual y tendencias te permitirá diferenciarte de la competencia y ofrecer un servicio mucho más profesional y atractivo para tus futuros clientes."],["p","Y para que puedas visualizarlo mejor, te mostraremos un ejemplo práctico de mood board que hemos creado como fuente de inspiración:"],["li","Como puedes observar, un mood board es un tablero de inspiración que reúne una lluvia de ideas visuales con el objetivo de dar forma al diseño de cualquier espacio o detalle de una boda. A través de imágenes, colores, texturas y elementos clave, conseguimos plasmar el estilo deseado y facilitar la comprensión del concepto global tanto para la pareja como para el equipo de proveedores."],["li","Sin embargo, queremos dejarte algo muy claro: el mundo del diseño es un ámbito especializado y complejo. Como ya hemos mencionado en otras ocasiones, a veces caemos en el error de pensar que por tener buen gusto o amar la decoración ya estamos capacitados para diseñar profesionalmente... y esto no siempre es cierto."],["p","El diseño requiere conocimientos específicos, dominio de la composición, la armonía visual, las proporciones, las tendencias, el uso del color y mucho más. Por eso, si realmente quieres ofrecer este servicio con garantías y calidad, es fundamental formarte adecuadamente."],["p","Cuando llegue el momento, te animamos a buscar una formación específica en diseño para eventos o bodas. Te aseguramos que notarás una evolución significativa en tu trabajo y, sobre todo, en la seguridad con la que abordarás cada proyecto creativo."],["h","Cómo ejecutar el trabajo de un diseño y llevarlo a la acción"],["p","Una vez definido y aprobado el diseño, llega el momento de convertir esa inspiración en realidad. Para ello, deberás buscar y coordinar a los proveedores adecuados que te ayudarán a materializar cada elemento del diseño que has plasmado en imágenes."],["p","Esto incluye contactar con empresas de papelería para la elaboración de invitaciones y cartelería, seleccionar el mobiliario ideal en empresas de alquiler, trabajar con floristas para desarrollar las composiciones florales, y buscar detalles personalizados para las mesas o espacios clave del evento."],["p","Paso a paso, irás reuniendo todos los materiales necesarios para dar forma a la estética de la boda, asegurándote de que cada pieza encaje a la perfección con el estilo definido y con la personalidad de la pareja. Así, conseguirás que el diseño cobre vida de forma coherente, armónica y profesional para el gran día."]]},{"k":"5-4","t":"Coordinación y wedding book","b":[["p","Como ya hemos mencionado, la Coordinación de la boda consiste en un acompañamiento y supervisión minuciosa, basada en un timing detallado y en un plan previamente consensuado con la pareja y con todos los proveedores implicados. Este servicio resulta esencial para que todo lo que se ha programado y diseñado durante meses se ejecute sin contratiempos."],["p","Debes tener muy presente que, por más perfecto que sea el diseño o la planificación, sin una buena coordinación el día del evento puede desmoronarse. De hecho, una de las razones por las que nuestros clientes, así como proveedores como caterings, fotógrafos o floristas, suelen felicitarnos al finalizar una boda, es por nuestra rigurosa gestión del timing."],["p","El timing es un documento clave que divide, por franjas horarias, todos los momentos importantes de la boda, desde los preparativos de los novios hasta el cierre del evento. Para elaborarlo, deberás reunirte con la pareja y acordar, de manera realista y objetiva, cuánto tiempo se dedicará a cada fase del día. Eso sí, ten en cuenta que es fundamental contemplar posibles imprevistos, como traslados largos o movimientos de invitados entre espacios diferentes, que suelen generar retrasos."],["p","En este sentido, también será crucial que tu equipo esté informado y bien preparado para facilitar esos movimientos y actuar en el momento adecuado. Una de nuestras estrategias más efectivas es crear un timing adicional para los montajes y desmontajes de proveedores, consultando con ellos con antelación cuánto tiempo necesitan y programando sus llegadas con un margen de seguridad."],["p","Además del timing, existe otro documento imprescindible que deberás elaborar para que todo salga perfecto: el Wedding Book. Te hablaremos de él a continuación."],["h","Qué es un Wedding Book y para qué se utiliza"],["p","El Wedding Book es un documento fundamental que recoge, de manera detallada y ordenada, toda la información clave relacionada con el día de la boda. Su principal objetivo es servir como guía para ti y tu equipo de coordinación, permitiéndoos tener a mano todos los datos necesarios para resolver cualquier imprevisto con rapidez y eficacia."],["p","En este documento debe incluirse desde el inicio hasta el final del evento:"],["li","Direcciones importantes, como los lugares donde se prepararán los novios o el espacio donde se celebra la boda."],["li","Horarios detallados y cronograma del día."],["li","Datos de contacto de todos los proveedores involucrados."],["li","Momentos especiales en los que se requiera una intervención específica, como la gestión de sorpresas, discursos, entradas especiales o entregas simbólicas."],["li","Por ejemplo, si durante el montaje del evento estás ocupada organizando los últimos detalles y el fotógrafo necesita urgentemente la dirección donde se encuentra el novio, cualquier miembro de tu equipo podrá consultar el Wedding"],["li","Book y ofrecerle la información al instante."],["li","Gracias a este documento, el trabajo en equipo se vuelve más fluido, profesional y autónomo, garantizando que cada fase del evento esté bajo control y que todas las partes implicadas estén coordinadas en tiempo y forma."],["h","Cómo elaborar el Wedding Book de una boda"],["p","Para elaborar un buen Wedding Book, es fundamental contar con la máxima cantidad de información posible sobre el evento y organizarla de forma clara y accesible, de modo que cualquier miembro del equipo pueda consultarla en cualquier momento y resolver dudas o imprevistos con agilidad."],["p","Cada profesional tiene su propia manera de crear este tipo de herramienta, y con el tiempo tú también irás desarrollando tu propio método. Sin embargo, lo que a nosotras nos funciona especialmente bien es seguir este proceso en dos fases:"],["p","1- Elaborar un timing detallado donde se marquen todos los momentos clave de la boda: desde la llegada de proveedores y montaje, hasta los discursos, sorpresas o cualquier intervención especial."],["p","2- A partir de ese timing, desarrollar el Wedding Book, completándolo con toda la información necesaria:"],["li","Datos personales y de contacto de la pareja."],["li","Direcciones de los lugares importantes (preparativos, ceremonia, celebración)."],["li","Listado de proveedores con contacto directo y horarios de llegada."],["li","Tiempos estimados de montaje y desmontaje."],["li","Detalles específicos a tener en cuenta (sorpresas, rituales, protocolos, cambios de último momento)."],["li","La clave está en que este documento sea claro, práctico y completo, convirtiéndose en la herramienta de referencia para todo el equipo durante el Gran Día."]]},{"k":"5-5","t":"Estrategias y secretos que nos han funcionado","b":[["p","En esta sección de la formación, te explicaremos detalladamente cómo desarrollar todos los aspectos mencionados anteriormente y compartiremos contigo todo lo que a nosotros nos ha funcionado de forma real y efectiva."]]}]$j$::jsonb,
  $j$[{"k":"5-e0","t":"Tu primer mood board","b":[["p","BOARD En este módulo te animamos a dar rienda suelta a tu creatividad creando un mood board de una boda ideal para tu nicho de mercado. Es el momento perfecto para aplicar todo lo aprendido hasta ahora y disfrutar del proceso. ¿Quién sabe?"],["p","Tal vez este diseño pueda servir como base para tu próximo shooting. ¡Atrévete a soñar y a dar forma a tus ideas!"],["p","Para nosotros, esta es, sin duda, una de las partes más emocionantes de todo el proyecto de una boda. Lo más importante durante este ejercicio es que te permitas soñar, experimentar, investigar y dar forma a propuestas nuevas y originales. El objetivo es claro: dotar a cada boda de una personalidad única y auténtica."],["p","Disfruta al máximo este ejercicio. No pongas límites a tu imaginación, porque en este mundo, ¡todo es posible! Y eso es, precisamente, lo más extraordinario de nuestro trabajo."],["p","Cuando finalices tu mood board, envíanos tu propuesta a hola@nubesdealgodonevents.com y agendaremos nuestra próxima tutoría."],["p","Aprovecha también para anotar todas las dudas que te hayan surgido durante el Módulo 5 y compártelas con nosotros para que podamos resolverlas juntos."],["p","Y no olvides esta poderosa frase:"],["li","La creatividad es ver lo que otros ven, pero pensar lo que nadie ha pensado."],["p","¡FELICIDADES! Has completado el Módulo 5 y ya dominas en profundidad los tres grandes servicios que puedes ofrecer con tu empresa de Wedding Planner."],["p","Sabemos que tu mente está en plena ebullición, llena de ideas, inspiración y, sobre todo, con muchísimas ganas de pasar a la acción. Seguramente ya has empezado a crear material, soñar con tus primeras bodas y visualizar cómo será tu marca."],["p","Estamos muy orgullosos de ti. Has recorrido un gran tramo del camino y este impulso es exactamente lo que necesitas para continuar avanzando. ¡Sigue así! Este es el mejor rumbo para alcanzar tus metas."],["p","Y no lo olvides:"],["li","El crecimiento comienza al final de tu zona de confort. Atrévete, sueña, inventa, crea, deja volar tu imaginación. Sé diferente... y destacarás."]]}]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (6,3,1,'Cómo poner precio a tus servicios',1,'',true,
  $j$[{"k":"6-0","t":"Cómo calcular tus honorarios","b":[["p","Definir el precio de tus servicios será una de las decisiones más importantes que tomarás al iniciar tu empresa, y no será algo estático: será un proceso que evolucionará contigo. A medida que crezcas, ganes experiencia y tu perfil de cliente cambie, también lo harán tus tarifas."],["p","Es completamente normal que al principio ofrezcas tus servicios a un precio más accesible, especialmente si estás orientada a un público con un presupuesto más limitado. Sin embargo, con el tiempo —y si tu empresa empieza a trabajar con clientes de un nivel adquisitivo más alto— el valor de tu trabajo también deberá ajustarse en consecuencia."],["p","Ahora bien, llega la gran pregunta... ¿Cómo calcular correctamente el precio de los servicios que vas a ofrecer?"],["p","En los próximos puntos te ayudaremos a analizar todos los factores que debes tener en cuenta para establecer un precio justo, coherente y rentable. ¡Vamos paso a paso!"],["p","MÓDULO 6 – CÓMO ESTABLECER EL PRECIO A TUS SERVICIOS"]]},{"k":"6-1","t":"Cómo, cuándo y a quién cobrar","b":[["p","Para definir correctamente el precio de tus servicios y asegurar la viabilidad económica de tu empresa, es fundamental realizar una previsión financiera realista y establecer objetivos claros para el primer año de actividad."],["p","Empieza respondiendo a estas preguntas clave:"],["p","¿Cuáles serán tus gastos fijos mensuales y anuales? (Ej. cuota de autónomos, seguros, teléfono, alquiler de local, impuestos, gasolina…). ¿Qué ingresos totales te gustaría obtener al finalizar el año? ¿Cuántas bodas te propones organizar en ese periodo? ¿Qué sueldo mensual quieres asignarte?"],["p","Con estas respuestas, realiza los siguientes cálculos:"],["p","1- Suma todos tus gastos mensuales y multiplícalos por 12. 2- Suma tus gastos anuales a ese resultado. 3- Multiplica por 12 el sueldo mensual que te gustaría obtener."],["p","4- Suma el total de gastos con el total del sueldo anual para obtener la cantidad que deberás generar al año."],["p","5- Divide esa cantidad entre 12 para conocer tus ingresos mensuales mínimos necesarios."],["p","6- Divide el total anual entre el número de bodas estimadas para saber cuánto deberías cobrar por cada una."],["p","Ejemplo práctico:"],["li","Gastos mensuales: 400 €"],["li","Gastos anuales: 1.000 €"],["li","Objetivo de bodas anuales: 17"],["li","Sueldo mensual deseado: 2.500 €"],["li","Cálculo: necesarios) dossier de tarifas, donde detalles claramente tus servicios y honorarios. Tranquila, dispones de una plantilla en los descargables que puede servirte de guía para crear la tuya."],["p","400 € x 12 = 4.800 € 4.800 € + 1.000 € = 5.800 € (total de gastos anuales) 2.500 € x 12 = 30.000 € (sueldo anual) 5.800 € + 30.000 € = 35.800 € (ingresos mínimos anuales 35.800 € / 12 = 2.983,33 € (ingresos mensuales mínimos) 35.800 € / 17 bodas = 2.105,88 € por boda Una vez tengas esta cifra, el siguiente paso será elaborar un"],["p","¿Cuándo cobrar tus servicios?"],["p","Aunque esto dependerá de tu planificación y volumen de bodas anuales, te compartimos nuestro método, que nos ha funcionado con éxito:"],["li","Primer pago: 30% del total de tus honorarios como paga y señal, en el momento de reservar la fecha."],["li","Segundo y tercer pago: 20% cada uno, en los meses intermedios. No establecemos una fecha fija en el presupuesto; esto nos da flexibilidad para adaptar nuestros ingresos y distribuirlos de forma equilibrada a lo largo del año."],["li","Pago final: 30%, un mes antes de la boda."],["li","Contamos con un calendario de ingresos (disponible en los descargables) que nos ayuda a organizar los segundos pagos según los meses en los que más nos conviene recibirlos. Solo es necesario avisar a cada pareja con antelación del momento en que deben realizar su segundo abono."],["li","Este método te permitirá mantener la salud financiera de tu empresa, tener ingresos constantes y mejorar la planificación económica a lo largo del año."],["li","PAGOS NOTAS"],["p","01. 02. 03. 04."],["p","SUN MON TUE WEN THU FRI SAT"]]},{"k":"6-2","t":"Estrategias y secretos que nos han funcionado","b":[["p","Creemos firmemente que este es uno de los temas que más inquietud genera al iniciar una empresa, por eso te animamos a que anotes todas tus dudas en un documento digital y nos las envíes a hola@nubesdealgodonevents.com para poder resolverlas juntas en nuestra próxima tutoría. ¡Tranquila! Sabemos que al principio todo puede parecer una gran incertidumbre, pero estamos aquí para ayudarte a reconducir cualquier aspecto que te genere inseguridad."],["p","Has superado el Módulo 6 y tu proyecto empieza a tomar forma. ¡Estamos muy felices de ver tu compromiso, tus ganas y tu motivación! No tenemos dudas de que vas a llegar muy lejos."],["p","Y no lo olvides:"],["li","Elúnico modo de hacerun gran trabajo es amar lo que haces."]]}]$j$::jsonb,
  $j$[]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (7,4,0,'Planificación de una boda',1,'En nuestra próxima tutoría, resolveremos todas las dudas que tengas sobre la planificación de bodas. Te recomendamos que las vayas anotando en un documento digital y nos las envíes a hola@nubesdealgodonevents.com para que podamos agendar la videollamada y aprovechar al máximo ese tiempo juntos. ¡ENHORABUENA! Has completado el módulo 7 y estamos a punto de finalizar el temario. ¡Estás haciendo un trabajo increíble! Esperamos que estés absorbiendo todos estos conocimientos con ilusión y motivación, porque sin duda te están acercando a crear algo grande. Y no olvides esta frase tan inspiradora: El éxito no se logra solo con cualidades especiales. Es sobre todoun trabajo de constancia, de método y de organización.',true,
  $j$[{"k":"7-0","t":"Presupuesto","b":[["p","Lo primero que debemos hacer antes de comenzar con la planificación de una boda es conocer el presupuesto disponible. Para ello, es fundamental preguntar a la pareja cuál es el presupuesto real con el que cuentan para organizar su boda. Esta información será la base sobre la que estructuraremos todo el proceso de organización y toma de decisiones."]]},{"k":"7-1","t":"Planificación","b":[["p","Justo después de concretar el presupuesto con la pareja, es momento de distribuirlo de acuerdo con sus prioridades. Para ello, deberás utilizar la plantilla mencionada en el módulo 6 \"Organización Integral\", donde se enumeran los proveedores necesarios para la boda y se asigna un presupuesto orientativo para cada uno. (Recuerda que en los descargables dispones tanto de una plantilla vacía como de un ejemplo real que te servirá de guía)."],["p","Esta herramienta te permitirá llevar un control detallado de los gastos, facilitando la supervisión constante del presupuesto global."],["p","Una vez realizada esta distribución, comenzarás con la búsqueda de proveedores. El primer paso será localizar el espacio ideal para la celebración. Para hacer una búsqueda eficaz, es fundamental recopilar previamente toda la información posible sobre las necesidades, estilo y preferencias de tus clientes. Esto te permitirá hacer una preselección ajustada y presentarles opciones acordes."],["p","Nosotros solemos proponer entre 3 y 5 espacios que se ajusten prácticamente al 100% a lo que busca la pareja. Antes de presentarlos, nos aseguramos de que tienen disponibilidad en la fecha de la boda. Enviamos los dossieres de información y, tras su revisión, organizamos las visitas con la pareja. Casi siempre, uno de estos lugares se convierte en el elegido."],["p","Una vez elegido el espacio, se continúa con la selección del resto de proveedores. Al igual que con los venues, solemos ofrecer tres opciones por tipo de proveedor (fotógrafo, DJ, etc.), asegurándonos previamente de que estén disponibles en la fecha elegida."],["p","Es fundamental mantener tu base de datos actualizada."],["p","Muchos proveedores cambian sus tarifas y materiales promocionales con regularidad, así que asegúrate siempre de tener la versión más reciente antes de compartirla con tus parejas."],["p","Además de la plantilla de organización, te recomendamos complementar tu trabajo con herramientas como Trello o Google Calendar, que te permitirán mantener una agenda estructurada y una planificación más eficiente de reuniones y tareas."],["p","BODA PRESUPUESTO PRODUCCIÓN PLANIFICACIÓN"],["p","Te sugerimos seguir este orden para buscar a los proveedores, ya que algunos se reservan con mucha antelación:"],["li","Espacio"],["li","Catering"],["li","Fotógrafo / Videógrafo"],["li","DJ y técnicos"],["li","Alquiler de mobiliario y decoración"],["li","Música en vivo"],["li","Vestido de novia"],["li","Invitaciones"],["li","Detalles"],["li","Vestido de novio"],["li","Maquillaje y peluquería"],["li","Seguir este orden te ayudará a priorizar la contratación de los proveedores más solicitados, evitando perder oportunidades clave por falta de disponibilidad."]]},{"k":"7-2","t":"Producción","b":[["p","A medida que vayas cerrando proveedores, comenzarás de forma paralela con la fase de producción de todos los elementos que habéis ideado o diseñado junto a la pareja. Este proceso es fundamental para que todo cobre forma y se ajuste al estilo y expectativas de tus clientes."],["p","Será tu responsabilidad buscar empresas especializadas que puedan encargarse de producir los distintos elementos decorativos y detalles personalizados. En caso de ser necesario, deberás acudir personalmente al showroom de la empresa de alquiler de mobiliario para seleccionar el material más adecuado, asegurándote de que armonice con el estilo elegido y la paleta de colores definida para la boda."],["p","Además, deberás prestar atención a otros aspectos esenciales como la música. Para ello, es imprescindible que el DJ facilite a la pareja una plantilla con un guion estructurado y una escaleta detallada de los distintos momentos del evento. Esta herramienta permitirá a los novios indicar qué canciones desean en cada momento importante, facilitando así una planificación musical personalizada y coherente."],["p","Una vez recibida la plantilla, el DJ deberá asegurarse de que todas las canciones estén correctamente descargadas y que las versiones solicitadas por la pareja sean las adecuadas."],["p","Como cierre de este proceso, aproximadamente un mes antes del evento, deberás coordinar una reunión con todos los proveedores implicados. El objetivo será revisar todo lo producido y confirmar que cada detalle está listo para ser ejecutado de manera precisa y eficaz el día de la boda. Esta última comprobación es clave para garantizar el éxito de la celebración."]]},{"k":"7-3","t":"Seguimiento de clientes","b":[["p","A medida que la planificación de la boda avanza, descubrirás que la plantilla de organización se convierte en una herramienta dinámica y fundamental para gestionar toda la información del evento de forma estructurada y eficiente. Este documento será el eje central donde recopiles todos los aspectos clave de la boda: lista de invitados, reuniones, control de gastos, ideas de inspiración, entre otros."],["p","Podrás adaptar esta plantilla según tus necesidades, añadiendo o eliminando apartados en función de lo que mejor se ajuste a tu forma de trabajar. Además, te recomendamos compartirla con las parejas, permitiéndoles participar activamente en su actualización. Es lo que nosotras hacemos con cada una de nuestras parejas, y se ha demostrado como una excelente estrategia de colaboración."],["p","Trabajar de forma conjunta en una plantilla compartida (por ejemplo, mediante Google Drive) facilita una comunicación fluida, una organización transparente y un seguimiento constante. De este modo, tanto tú como tus clientes podréis ir actualizando datos relevantes como inspiración visual, lista de invitados con alergias o intolerancias, distribución de las mesas, entre otros muchos detalles que deberás tener muy controlados el día del enlace."],["p","Este sistema no solo fortalece la relación con tus clientes, sino que te permitirá ofrecer un servicio profesional, ordenado y altamente personalizado."],["p","En esta sección de la formación, te guiaremos paso a paso para que puedas desarrollar todos los aspectos que hemos tratado previamente."],["p","Además, compartiremos contigo las estrategias y acciones concretas que nosotras hemos implementado y que nos han resultado clave para lanzar con éxito nuestra empresa, atraer a nuestros primeros clientes potenciales y organizar la primera boda."],["p","Nuestra intención es que puedas aplicar estos aprendizajes de forma práctica, adaptándolos a tu propio proyecto para que consigas consolidarlo con confianza y profesionalidad desde el inicio."]]},{"k":"7-4","t":"Estrategias y secretos que nos han funcionado","b":[]}]$j$::jsonb,
  $j$[]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (8,4,1,'Marketing para tu empresa',1,'En nuestra próxima tutoría, resolveremos todas las dudas que tengas sobre la publicidad y marketing. Te recomendamos que las vayas anotando tus dudas en un documento digital y nos las envíes a hola@nubesdealgodonevents.com para que podamos agendar la videollamada y aprovechar al máximo ese tiempo juntos. Una vez más… ¡FELICIDADES! Estamos ya muy cerca del final y no podemos estar más orgullosos de ti. ¡Estás demostrando que puedes con todo y que vas a lograr lo que te propongas! Te animamos, como siempre, a que pongas todo tu cariño en cada una de tus creaciones, porque no solo son ejercicios, pueden convertirse en tus primeros materiales reales, listos para compartir públicamente y comenzar a posicionar tu marca. Y no olvides algo fundamental: La mejor forma de empezar algo es dejar de hablar de ello y ponerse a hacerlo.',true,
  $j$[{"k":"8-0","t":"Formas de difundir tu trabajo","b":[["p","Como mencionamos en el Módulo 2, en el apartado \"Cómo crear un plan de acción de empresa\", además de todas las gestiones internas necesarias para poner en marcha tu negocio y mantenerlo activo, es fundamental tener en cuenta las estrategias de difusión para lograr visibilidad y captar clientes."],["p","A continuación, te compartimos algunas estrategias efectivas que pueden ayudarte a posicionarte y atraer a tu cliente ideal."],["p","No obstante, con el tiempo, tú misma descubrirás cuáles son las que mejor se adaptan a tu estilo de trabajo y al perfil de tu empresa."]]},{"k":"8-1","t":"Tu página web","b":[["p","Lo primero que te recomendamos es construir una Presencia Digital Sólida, ya que, hoy en día, si no eres visible en internet, es como si no existieras."],["p","Tu presencia online debe reflejar tu estilo, profesionalidad y propuesta de valor, y ayudarte a conectar directamente con tu cliente ideal."],["p","MÓDULO 8 – MARKETING PARA TU EMPRESA"],["p","Página web profesional Crea una web atractiva, funcional y alineada con tu marca."],["p","Esta debe incluir:"],["li","Un portafolio con imágenes de tus trabajos o proyectos inspiracionales."],["li","Testimonios reales o simulados (al inicio) que transmitan confianza."],["li","Una descripción clara de los servicios que ofreces."],["li","Un formulario de contacto sencillo y directo."],["li","Blog"],["li","Añade valor mediante la publicación de contenido útil y de interés para tus clientes potenciales, como por ejemplo:"],["p","“Tendencias en bodas 2025” “Errores a evitar al organizar tu boda” “Cómo elegir al proveedor perfecto”"],["p","A los futuros novios les gusta conocerte desde un enfoque cercano, entender cómo trabajas y sentirse identificados contigo. Recuerda: en este sector, la confianza, la conexión emocional y la transparencia son claves. Mostrarte en tu blog hablando con naturalidad, compartiendo experiencias o resolviendo inquietudes típicas de las parejas, puede ser lo que marque la diferencia y les impulse a contratarte."],["p","SEO (Posicionamiento en Google)"],["p","Es fundamental que tu web esté optimizada para aparecer en los resultados de búsqueda cuando alguien busque términos como\"Wedding Planner en [tu ciudad o zona]\". Para ello:"],["li","Usa palabras clave relevantes en los títulos y descripciones de tu web."],["li","Crea contenido regular en tu blog que incluya estas palabras clave."],["li","Asegúrate de que tu página cargue rápido y sea compatible con móviles."],["li","Si puedes invertir desde el inicio, lo ideal es contar con una agencia de marketing especializada para ayudarte a posicionarte profesionalmente. No obstante, si tu presupuesto es ajustado, puedes comenzar con recursos gratuitos disponibles online que te enseñen los conceptos básicos de"],["li","SEO. Más adelante, cuando tu negocio crezca, siempre estarás a tiempo de dar el salto a una estrategia más profesional."],["li","La clave está en comenzar con calidad, coherencia y constancia."]]},{"k":"8-2","t":"Redes sociales","b":[["p","Te recomendamos que pongas en marcha tus redes sociales desde el principio, asegurándote siempre de que respeten tu imagen corporativa y que el contenido que compartas sea de calidad y coherente con tu marca."],["p","Si al inicio aún no cuentas con material profesional como fotografías o vídeos de bodas reales, no te preocupes: puedes empezar a crear contenido tú misma. Grábate durante tus visitas a espacios, toma fotos de tus procesos creativos en casa, muestra detalles de decoración, elabora vídeos breves con ideas“handmade”que puedan inspirar a tus seguidores…"],["p","Este tipo de contenido es cercano, valioso y muy atractivo para las parejas que están comenzando a planificar su boda."],["p","Además, les permitirá conocer tu estilo de trabajo y tu personalidad, creando conexión y confianza."],["p","Algunos aspectos clave para tener en cuenta en tus publicaciones:"],["li","Instagram y Pinterest son tus mejores aliados, ya que el sector nupcial es altamente visual. Apuesta por imágenes bonitas, estéticamente cuidadas y con un estilo coherente."],["li","Publica contenido variado: fotos de inspiración, imágenes del “detrás de cámaras” (behind-the-scenes), testimonios de parejas, fragmentos de tu día a día como wedding planner…"],["li","Utiliza hashtags específicos y relevantes como aumentar tu visibilidad y a que las parejas adecuadas te encuentren más fácilmente. novias reales que estén dispuestas a compartir su experiencia. El contenido auténtico tiene mucho más impacto y credibilidad. empresas como si fuera propio. Aunque parezca obvio, es una práctica más común de lo que debería, y puede perjudicar seriamente tu reputación profesional. La autenticidad es tu mejor carta de presentación. creatividad y profesionalismo. ¡Eso será lo que conecte de verdad con tu cliente ideal!"],["p","#bodas2025, #weddingplanner[tu ciudad], #decoraciondebodas, entre otros. Esto te ayudará a Establece colaboraciones con influencers del sector o con Y muy importante: jamás utilices contenido de otras Recuerda: lo esencial es mostrar tu esencia con sinceridad,"],["h","Cómo gestionar tus redes sociales"],["p","Debes tener algo muy claro: Internet es el medio de difusión más potente que existe, y si no estás presente en él, es como si no existieras."],["p","Hoy en día, la visibilidad online es imprescindible para cualquier profesional que quiera destacar, y mucho más en un sector como el de las bodas, donde la inspiración visual y la confianza son claves para captar clientes."],["p","Por eso, te recomendamos que dediques parte de tu tiempo a crear contenido para redes sociales y trabajes activamente en tu presencia digital. No tiene sentido realizar un gran trabajo interno si luego nadie puede verlo ni encontrarte. Tu visibilidad es lo que hará que las parejas conozcan tu trabajo, conecten contigo y te contraten."],["p","Sabemos que al principio puede parecer una tarea abrumadora —la gestión de redes sociales implica tiempo, constancia y estrategia—, pero debes asumirlo como una parte fundamental de tu profesión. Es una inversión que dará frutos si la haces con planificación y calidad."],["p","Si en este momento no puedes permitirte contratar una empresa especializada que gestione tus redes, no te preocupes: puedes hacerlo tú misma. Aquí van algunos consejos:"],["li","Crea un calendario de publicaciones: planifica tus contenidos con antelación. Esto te dará claridad y te evitará improvisaciones de última hora."],["li","Sé constante: la regularidad es más importante que la cantidad. Publica con frecuencia, aunque sean pocos posts por semana, pero mantén el ritmo."],["li","Prepara el contenido con antelación: organiza sesiones para crear fotos, escribir textos o grabar vídeos que puedas ir publicando poco a poco."],["li","Utiliza herramientas de programación como Planoly, Later,"],["li","Metricool o incluso el Business Suite de Meta para programar tus publicaciones y optimizar tu tiempo."],["li","Recuerda: la profesionalidad también se refleja en tu presencia online. Cuida lo que compartes, sé auténtica y crea una imagen coherente con tu marca. Esto será clave para atraer al tipo de cliente que deseas."],["h","Qué tipo de contenido debes publicar"],["p","Te lo hemos comentado en varias ocasiones, pero es realmente crucial que tengas siempre presente que el contenido que publiques debe ser de alta calidad."],["p","Tu imagen lo es todo. Y si no cuidas lo que muestras al mundo, estarás proyectando una imagen que no atraerá al tipo de cliente con el que sueñas trabajar. Publicar contenido poco trabajado, con errores o sin una estética definida puede afectar negativamente a tu marca. Por eso:"],["li","Cuida cada palabra: escribe sin faltas de ortografía, con mensajes claros, coherentes y alineados con tu estilo y tu cliente ideal."],["li","Investiga: entiende a fondo qué le interesa a tu audiencia."],["li","Observa sus gustos, aspiraciones y necesidades."],["li","Sé constante y auténtica: muestra quién eres, qué te inspira y cómo trabajas."],["li","Para una empresa de Wedding Planner, las redes sociales deben inspirar, informar y generar confianza. A continuación, te compartimos los formatos de contenido que actualmente están funcionando mejor y que te pueden ayudar a destacar:"],["h","Contenido en Vídeo (Reels, TikToks, Shorts)"],["p","Before & After de la decoración del espacio."],["p","Timelapses del montaje."],["p","Detrás de cámaras: preparación, selección de flores, pruebas de menú, etc."],["p","Reacciones de los novios al ver su boda montada."],["p","Mini vlogs: un día en la vida de una Wedding Planner."],["h","Fotos y Carruseles Impactantes"],["p","Imágenes detalladas de decoraciones reales."],["p","Moodboards con paletas de colores."],["p","Consejos visuales en formato gráfico."],["p","Antes y después de una boda."],["h","Contenido Educativo"],["p","Errores frecuentes en la organización y cómo evitarlos."],["p","Checklist por meses de planificación."],["p","Presupuesto: dónde ahorrar y dónde invertir."],["p","Tendencias del 2025: flores, estilos, paletas de color."],["p","Diferencias entre un Wedding Planner y un Coordinador del Día B."],["h","Historias de Clientes"],["p","Vídeos con testimonios reales."],["p","Publicaciones con la historia de los novios y su gran día."],["p","Capturas de agradecimientos o valoraciones."],["h","Interacción con la Comunidad"],["p","Encuestas y preguntas (“¿Boda de día o de noche?”,“¿Estilo clásico o boho?”)."],["p","Retos virales o tendencias del sector: “Esto nos pidieron vs. esto hicimos”."],["h","Contenido Viral y de Entretenimiento"],["p","Memes relacionados con la profesión."],["p","Situaciones divertidas del día a día de una Wedding Planner."],["p","Frases inspiradoras que conecten con el amor y la organización de bodas."],["h","Colaboraciones"],["p","Directos o entrevistas con otros proveedores: floristas, maquilladores, músicos..."],["p","Menciones cruzadas en redes: etiquétalos y pídeles que hagan lo mismo contigo."],["h","Mostrando tu Marca Personal"],["p","Muéstrate tú. Habla a cámara, presenta tu equipo, cuenta por qué amas tu trabajo."],["p","Comparte tus opiniones sobre nuevas tendencias o estilos que te inspiran."],["p","Este mix de contenido no solo te diferenciará, sino que también te posicionará como una profesional cercana, experta y comprometida. Sabemos que es mucha información y puede abrumarte, pero no te preocupes: todo esto puedes aplicarlo poco a poco y a tu ritmo."],["p","Tú eliges por dónde empezar y qué te funciona mejor. Lo importante es dar el primer paso, probar, aprender y evolucionar."],["p","Recuerda siempre: Lo que hoy parece difícil, mañana será parte de tu historia de éxito."]]},{"k":"8-3","t":"Blogs y revistas de bodas","b":[["p","Los blogs de bodas son una plataforma de referencia para muchas parejas, especialmente para las novias, que comienzan a investigar ideas, tendencias y estilos tan pronto como se comprometen. Por eso, como ya hemos comentado en profundidad al hablar de los shootings como herramienta clave de difusión, estos medios representan una excelente oportunidad para ganar visibilidad y posicionarte dentro del sector nupcial."],["p","Participar en blogs o revistas especializadas puede marcar un antes y un después en la proyección de tu empresa. Las principales formas de hacerlo son:"],["li","Publicando shootings o editoriales: compartir material original, estéticamente atractivo y bien producido, con un enfoque claro y un storytelling potente."],["li","Colaborando con entrevistas: muchas plataformas buscan voces expertas y experiencias reales. Compartir tu historia, consejos o visión del sector puede ayudarte a conectar con tu audiencia."],["li","Ofreciendo publicidad o visibilidad a tus servicios: en ocasiones, puedes valorar invertir en una publicación patrocinada o espacio publicitario que refuerce tu presencia."],["li","Estar presente en estos canales no solo te posicionará como una profesional de referencia, sino que también reforzará tu imagen de marca y atraerá a parejas que ya están activamente interesadas en organizar su boda."]]},{"k":"8-4","t":"Publicidad","b":[["p","Existen múltiples formas de hacer publicidad para tu empresa, y como en muchos otros aspectos del negocio, será fundamental que investigues, pruebes y analices qué tipo de promoción funciona mejor para ti y para tu público objetivo."],["p","Debes tener en cuenta que no existe una única fórmula mágica: el éxito de una campaña puede variar según el momento del año, el mensaje que transmitas o incluso la plataforma que elijas."],["p","Algunas opciones efectivas y económicas para empezar son:"],["li","Facebook Ads"],["li","Instagram Ads"],["li","TikTok Ads"],["li","Google Ads"],["p","Estas plataformas permiten lanzar campañas publicitarias con una inversión mínima y, si se gestionan correctamente, pueden darte una buena visibilidad desde el principio. Nuestra recomendación es que comiences con campañas pequeñas y, en función de los resultados obtenidos, las vayas optimizando o replicando."],["p","Antes de lanzar cualquier anuncio, es importante que te plantees algunos aspectos clave:"],["p","¿Es el momento adecuado para publicitarte? Existen épocas del año donde la demanda de servicios de Wedding Planner aumenta, como Navidad, San Valentín o los meses de verano, cuando muchas parejas se comprometen. ¿A qué hora está tu público más activo? La franja horaria de publicación puede marcar la diferencia en la visibilidad y efectividad de tu campaña. ¿Tienes claro tu mensaje y tu propuesta de valor?"],["p","Comunicar de forma clara quién eres, qué haces y por qué deberían elegirte es esencial para captar la atención del cliente ideal."],["p","Con estos puntos bien definidos, podrás tomar decisiones más estratégicas en tus acciones de marketing y aumentar tus posibilidades de éxito."]]},{"k":"8-5","t":"Portafolio","b":[["p","Tu portafolio es, sin duda, una de tus principales cartas de presentación. Por eso, te recomendamos que cuides cada detalle y que esté compuesto exclusivamente por imágenes de alta calidad y contenido que transmita claramente quién eres, cómo trabajas y, sobre todo, hacia qué tipo de cliente te diriges."],["p","Por ejemplo, si tu propósito es atraer a un perfil de pareja que busca bodas de estilo boho, en entornos naturales, con un ambiente relajado y celebraciones al aire libre, evita incluir fotografías de bodas clásicas o religiosas que no representen ese estilo. Mostrar coherencia en tu portafolio es clave para que el cliente ideal se sienta identificado contigo desde el primer momento."],["p","Recuerda: tu portafolio debe hablar por ti incluso antes de que lo hagas tú."]]},{"k":"8-6","t":"Competencia","b":[["p","Para nosotros el trabajo en equipo y la creación de comunidad son fundamentales. Fomentar buenas relaciones con otras compañeras del sector no solo enriquece tu experiencia profesional, sino que también puede abrirte muchas puertas, especialmente cuando estás dando tus primeros pasos como Wedding Planner."],["p","Llevarse bien con la competencia tiene muchas más ventajas que inconvenientes. Cada empresa tiene su propio enfoque, estilo y, sobre todo, un tipo de cliente diferente. Por eso, no se trata de rivalidad, sino de comprender que hay espacio para todas y que un entorno colaborativo fortalece al conjunto del sector."],["p","La mejor forma de impulsar el crecimiento y el reconocimiento profesional en nuestro ámbito es, precisamente, generando vínculos de respeto, apoyo y colaboración con quienes comparten esta maravillosa profesión."]]},{"k":"8-7","t":"Herramientas para crear tu web","b":[["p","Queremos insistir en la enorme importancia que tiene, desde el punto de vista profesional, contar con una página web propia para tu empresa."],["p","Como te hemos comentado anteriormente, causar un buen impacto en internet es fundamental para ganar visibilidad y transmitir una imagen de empresa seria y consolidada. Por eso, te recomendamos que trabajes en la creación de una web y en su posicionamiento para captar nuevos clientes."],["p","Actualmente existen plataformas como WordPress o Wix que ofrecen plantillas muy intuitivas con las que puedes diseñar tu sitio web de forma sencilla y gratuita. Solo deberás pagar por el dominio cuando decidas publicarla."],["p","Además, queremos sugerirte algunas herramientas prácticas que te permitirán preparar contenido visual e incluso diseñar el aspecto de tu web antes de volcarlo en estas plataformas."],["p","Canva e InShot son dos de nuestros editores favoritos:"],["p","versátiles, fáciles de usar y con numerosos recursos gratuitos."],["p","Sabemos que esta es una tarea más en medio de todo lo que estás gestionando para lanzar tu empresa, pero te aseguramos que marcará la diferencia. Quizás no sea el momento de invertir en una web profesional, pero sí puedes empezar con una versión sencilla, siempre cuidando que el contenido sea de calidad, los mensajes estén claros y te representen bien."],["p","Ten en cuenta que cualquier cliente potencial que compare dos empresas similares, pero una con página web y otra que solo tiene presencia en redes sociales, lo más probable es que confíe más en la que tiene web. Por eso, te animamos a que incluir tu página como uno de los objetivos prioritarios de tu empresa."]]},{"k":"8-8","t":"Estrategias y secretos que nos han funcionado","b":[["p","En esta sección de la formación, te guiaremos paso a paso para que puedas desarrollar todos los aspectos que hemos tratado previamente."],["p","Además, compartiremos contigo las estrategias y acciones concretas que nosotras hemos implementado y que nos han resultado clave para lanzar con éxito nuestras campañas publicitarias y empezar a cerrar bodas."]]}]$j$::jsonb,
  $j$[{"k":"8-e0","t":"Inspiración para tu contenido","b":[["p","MATERIAL FOTOGRÁFICO Queremos que pongas a trabajar tu imaginación y creatividad."],["p","El ejercicio consiste en pensar en 4 ideas de inspiraciónque te gustaría desarrollar para obtener material fotográfico y audiovisual que puedas utilizar en tus redes sociales o en tu página web."],["p","Por cada inspiración, deberás anotar todos los recursos e ideas que se te ocurran para hacerla realidad."],["p","Ejemplo de inspiración: Una tarta de boda Recursos:"],["li","Buscar colaboración con una pastelería de confianza."],["li","Investigar opciones DIY para la decoración de la tarta."],["li","Fotografiar la tarta en distintos entornos para obtener material variado."],["li","Utilizar bengalas para crear efectos visuales atractivos en los vídeos."],["li","Grabar vídeos cortando la tarta o durante su montaje."],["li","Piensa en cuatro inspiraciones diferentes (puedes incluir imágenes si lo deseas) y describe en detalle qué materiales, proveedores, ideas creativas o escenarios usarías para darles vida. Sé libre, creativa y detallada. ¡Todo cuenta!"],["li","Cuando hayas recopilado todas tus ideas, envíanoslas por email a hola@nubesdealgodonevents.com para poder agendar nuestra próxima videollamada. hacer realidad todas tus propuestas!"],["p","¡Estamos deseando ver cómo fluye tu creatividad y ayudarte a"]]}]$j$::jsonb)
on conflict (n) do nothing;

insert into public.course_modules(n,stage,position,title,hours,tutoria,published,lessons,exercises) values (9,4,2,'Habilidades sociales, imagen y actitud',1,'¡Has superado el Módulo 9 y, con ello, has completado todo el temario! Sabíamos desde el principio que serías capaz de asimilar cada uno de los contenidos que te hemos compartido, y también confiamos plenamente en que pondrás en práctica todo lo aprendido con pasión y compromiso. Pero ahora llega una pregunta clave... ¿Y ahora qué? Ahora es el momento de lanzarte con más fuerza que nunca.',true,
  $j$[{"k":"9-0","t":"Tu imagen personal","b":[["p","Ya hemos profundizado en la importancia de la imagen de tu empresa a nivel interno, pero ahora es momento de hablar de algo igual de relevante: tu imagen personal."],["p","Recuerda que, además de ser Wedding Planners, también somos comerciales de nuestros propios servicios. Y para vender con éxito, tu imagen debe transmitir confianza, profesionalidad y coherencia con lo que ofreces."],["p","Una imagen personal cuidada genera seguridad en tus clientes, mientras que una apariencia descuidada puede provocar el efecto contrario. Es esencial que te ocupes de tu presencia cada día, incluso si trabajas desde casa. Esto no solo influirá en cómo te ven los demás, sino también en cómo te sientes contigo misma: cuando te ves bien, te empoderas y afrontas los retos con otra actitud."],["p","Además, nunca sabes cuándo puede surgir una reunión o una videollamada inesperada, por lo que es importante estar siempre preparada."],["p","Cuida tu exterior, pero también tu interior. El bienestar personal se refleja en tu trato con los demás, en tu energía y en la manera en que proyectas tu profesionalidad."],["p","Y no olvides que el día de la boda, tu imagen es aún más clave."],["p","Según el tipo de boda, puede que necesites un uniforme u otro, pero siempre asegúrate de vestir acorde al estilo del evento y, sobre todo, de ir cómoda. Los días de boda suelen ser largos y muy activos, así que el equilibrio entre elegancia y funcionalidad será tu mejor aliado."]]},{"k":"9-1","t":"Relación con clientes y proveedores","b":[["p","La relación que mantengas con tus proveedores y compañeros del sector debe ser siempre profesional, cercana y cordial."],["p","Como ya hemos mencionado, en cada boda colaboran múltiples empresas, y es fundamental que cada proveedor dé lo mejor de sí para que todo se desarrolle según lo previsto y diseñado."],["p","Con muchos de estos profesionales trabajarás de forma recurrente, por lo que cuidar esa relación será clave."],["p","Agradecerás contar con colaboradores comprometidos y eficaces, y ellos también valorarán tu profesionalidad y trato humano."],["p","Por ejemplo, un fotógrafo con el que colabores en una boda puede compartir contigo todo el material capturado para que lo utilices en tus redes, web o portafolio. Si vuestra relación es buena y su trabajo de calidad, seguramente volverás a recomendarlo a otras parejas, lo cual beneficia a ambas partes. Es un claro\"win-win\": tú obtienes contenido valioso, y él gana visibilidad y más oportunidades."],["p","Además, cuando se construye una comunidad sólida y colaborativa, se crea un entorno de apoyo mutuo donde todos entienden el valor de compartir, recomendar y visibilizar el trabajo de los demás, especialmente en redes sociales y otros canales de difusión."],["p","Si en algún momento surge una situación en la que necesites hacer una sugerencia o expresar alguna diferencia, recuerda siempre abordarla en privado, con respeto y amabilidad. Evita desacreditar a un proveedor delante de tus clientes. Una comunicación clara y respetuosa os ayudará a mantener el foco en lo verdaderamente importante: ofrecer una experiencia excelente a las parejas."]]},{"k":"9-2","t":"Tu actitud profesional","b":[["p","La actitud lo es todo."],["p","Ya sabes que somos grandes admiradores de las frases motivadoras, de superación y crecimiento personal. Pero no es solo por afición: es porque creemos profundamente que la actitud con la que enfrentas las cosas es lo que marca la diferencia entre rendirte o avanzar, entre sufrir o disfrutar, entre bloquearte o crecer."],["p","Nuestro trabajo como Wedding Planners puede ser muy exigente. Habrá momentos de estrés, situaciones en las que te sentirás sola o incomprendida, especialmente si estás emprendiendo por tu cuenta. Habrá días en los que te parecerá que es imposible con todo, y eso es totalmente normal. Pero ahí es donde entra en juego tu fortaleza mental y tu capacidad de reacción."],["p","Tener la actitud adecuada te permitirá reconducir los bajones, respirar hondo, reorganizar tus ideas y volver al camino con más fuerza. Te enfrentarás a retos, sí, pero también verás cómo los vas superando uno a uno, alcanzando metas que antes te parecían lejanas."],["p","Así que no te desanimes, recuerda que esto es un proceso, y que estás creciendo cada día. Ponte objetivos claros, traza tu camino paso a paso y, lo más importante, confía en ti misma."],["p","Y si alguna vez sientes que flaqueas... no estás sola. Nosotros estamos aquí, acompañándote en cada etapa, apoyándote y guiándote para que consigas todo lo que te propongas. ¡Tú puedes!"]]},{"k":"9-3","t":"Relación con tu equipo","b":[["p","Como habrás notado, somos firmes defensoras del buen ambiente de trabajo, y creemos profundamente que para que un equipo funcione de manera eficiente, es imprescindible que reine una energía positiva. Para lograrlo, es fundamental fomentar la cordialidad, la educación y una relación sana entre todos los miembros del equipo."],["p","Ahora bien, además de promover este clima, también es necesario que sepas liderar. Un buen liderazgo no solo implica dirigir, sino también inspirar, organizar y mantener la armonía, asegurando al mismo tiempo que todo se lleve a cabo con profesionalidad."],["p","Antes de cada boda, es muy recomendable que organices una reunión con tu equipo. En ella, revisaréis juntos el Wedding Book y el timing del día, definirás claramente las tareas asignadas a cada persona, sus horarios, el uniforme requerido y los detalles específicos del evento. Este espacio también es perfecto para compartir inquietudes, ideas, sugerencias y cualquier observación relevante."],["p","Es muy importante que seas receptiva y flexible, que escuches a tu equipo y valores sus aportaciones. Eso generará confianza y compromiso."],["p","Si en algún momento necesitas corregir o hacer alguna observación a uno de tus compañeros o asistentes, hazlo siempre en privado, con respeto y desde la construcción, no desde la crítica. Una comunicación empática y asertiva es clave para mantener el respeto mutuo y seguir creciendo como equipo."],["p","Recuerda: un equipo motivado, valorado y bien dirigido es la base de una boda perfecta."]]},{"k":"9-4","t":"Relación con los novios","b":[["p","Está claro que la forma de comunicarnos en nuestra profesión no puede ser igual a la de un vendedor tradicional de otro tipo de productos o servicios. Como Wedding Planners, no solo ofrecemos organización y planificación, sino que también vendemos emociones, experiencias únicas y momentos irrepetibles."],["p","Cuando una pareja te contacta, te está confiando uno de los días más especiales y emotivos de su vida, por lo que nuestra comunicación debe ir mucho más allá de lo comercial. Es fundamental desarrollar una conexión emocional real, demostrar empatía, saber escuchar, ponerte en su lugar y disfrutar del proceso junto a ellos."],["p","La sensibilidad, la cercanía y la profesionalidad deben convivir en todo momento en tus palabras, gestos y actitudes. Es uno de los aspectos más bonitos de nuestra profesión: ver cómo el esfuerzo y dedicación invertidos se transforman en un día lleno de magia, felicidad y armonía."],["p","Aun así, no podemos perder de vista que estamos trabajando y debemos mantener una actitud profesional en todo momento, empleando siempre un lenguaje claro, educado y respetuoso."],["p","También es esencial que te asegures de adaptar tu forma de comunicarte, evitando tecnicismos o expresiones complejas que tus clientes puedan no entender. Tu objetivo debe ser siempre que todo quede perfectamente claro para ellos."],["p","Y, por supuesto, una sonrisa sincera, una actitud positiva y una energía cálida y confiable son tus mejores aliadas para generar la tranquilidad que tus parejas necesitan. Ellos deben sentir que, desde el primer momento, están dejando su gran día en las mejores manos."]]},{"k":"9-5","t":"Los invitados el día de la boda","b":[["p","Nuestra relación con los invitados el día de la boda debe ser siempre educada, cordial y cercana, sin perder nunca la firmeza necesaria en los momentos que así lo requieran."],["p","Especialmente en aquellas situaciones en las que debamos dirigir a los invitados de un lugar a otro, organizar actividades planificadas o simplemente pedir colaboración para que todo fluya según lo previsto."],["p","La comunicación con ellos debe ser siempre amable y con una sonrisa, mostrando disposición y atención a sus necesidades, dentro de nuestras posibilidades. No obstante, si en algún momento fuera necesario llamar la atención a algún invitado, ya sea por comportamiento o por entorpecer la dinámica del evento, debemos hacerlo de forma firme, pero siempre educada, discreta y profesional."],["p","Recuerda que en todo momento representas a la pareja que te ha contratado y tu comportamiento será un reflejo de su evento. Por ello, es fundamental encontrar el equilibrio entre la cercanía y la autoridad, transmitiendo confianza, respeto y buen criterio en cada interacción."],["p","9.5 Cómo relacionarte con los invitados el día de la boda Nuestra relación con los invitados el día de la boda debe ser siempre educada, cordial y cercana, sin perder nunca la firmeza necesaria en los momentos que así lo requieran."],["p","Especialmente en aquellas situaciones en las que debamos dirigir a los invitados de un lugar a otro, organizar actividades planificadas o simplemente pedir colaboración para que todo fluya según lo previsto."],["p","La comunicación con ellos debe ser siempre amable y con una sonrisa, mostrando disposición y atención a sus necesidades, dentro de nuestras posibilidades. No obstante, si en algún momento fuera necesario llamar la atención a algún invitado, ya sea por comportamiento o por entorpecer la dinámica del evento, debemos hacerlo de forma firme, pero siempre educada, discreta y profesional."],["p","Recuerda que en todo momento representas a la pareja que te ha contratado y tu comportamiento será un reflejo de su evento. Por ello, es fundamental encontrar el equilibrio entre la cercanía y la autoridad, transmitiendo confianza, respeto y buen criterio en cada interacción."]]},{"k":"9-6","t":"Estrategias y secretos que nos han funcionado","b":[["p","Este último módulo, en el que hablamos sobre la actitud y la imagen personal, es clave en tu camino como Wedding Planner. Por eso, en nuestra próxima tutoría te animamos a que nos plantees cualquier duda que te haya surgido al respecto."],["p","Además, aprovecha ese espacio para consultarnos cualquier otra inquietud que tengas. Sabemos que ahora estás arrancando con muchos frentes abiertos y queremos estar a tu lado en cada paso del proceso. ¡Recuerda que estamos aquí para apoyarte!"],["p","Desde el primer día te prometimos que no soltaríamos tu mano hasta que consigas tu objetivo, y lo cumpliremos. Así que, cuando te sientas preparada, envía todas tus preguntas a hola@nubesdealgodonevents.com y agendaremos nuestra próxima videollamada."],["p","Y sobre todo, no olvides una verdad fundamental: El éxito llega a quienes están demasiado ocupados persiguiéndolo."]]}]$j$::jsonb,
  $j$[]$j$::jsonb)
on conflict (n) do nothing;

-- Signature's extra module (promised on the web): hidden until you write it in Panel → Edición del curso → Signature
insert into public.course_modules(n,stage,position,title,hours,tutoria,published,plans) values (10,4,3,'Bodas destino y clientes internacionales',2,'',false,'{signature}')
on conflict (n) do nothing;

select count(*) as modulos from public.course_modules;  -- debe decir 10
